import {Label} from '@primer/react'
import {formatMoneyDisplay} from '../../utils/money'
import {getDiscountLabel} from '../../utils/discount'
import type {Customer} from '../../types/common'
import pluralize from 'pluralize'
import styles from './PlanCard.module.css'

interface CurrentPlanCardProps {
  customer: Customer
}

export default function CurrentPlanCard({customer}: CurrentPlanCardProps) {
  const isFreePlan = customer.plan.startsWith('free_')
  const isProPlan = customer.plan === 'pro'
  const notFreeOrProPlan = !isFreePlan && !isProPlan

  const getPlanName = (plan: string): string => {
    if (plan.startsWith('free_')) {
      return 'GitHub Free'
    }
    switch (plan) {
      case 'team':
        return 'GitHub Team'
      case 'pro':
        return 'GitHub Pro'
      default:
        return 'N/A'
    }
  }

  const getDisplayPrice = (): number => {
    if (customer.planPrice != null) {
      return customer.planPrice
    }
    return customer.paymentAmount
  }

  const getBasePrice = (): number | null => {
    if (customer.hasDiscount && customer.basePrice != null) {
      return customer.basePrice
    }
    return null
  }

  const hasDiscount = customer.hasDiscount ?? false
  const basePrice = getBasePrice()
  const discountLabel = getDiscountLabel({
    hasDiscount,
    isPercentageDiscount: customer.isPercentageDiscount,
    discountPercentage: customer.discountPercentage,
    discountAmount: customer.discountAmount,
  })

  return (
    <div className={styles.card} data-testid="current-plan-card">
      <div className={styles.planCard}>
        <div>
          <div className={styles.headingSection}>
            <p className={styles.cardHeading}>{getPlanName(customer.plan)}</p>
            {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
            {customer.hasPendingPlanChange && <Label className={styles.downgradeLabel}>Downgrade Pending</Label>}
          </div>
          <div className={styles.moneyContainer} data-testid="bill-section">
            <div>
              {hasDiscount && basePrice != null && (
                <span className={styles.strikethroughPrice}>
                  <span className="sr-only">Original price: </span>
                  {formatMoneyDisplay(basePrice, 2, true)}
                </span>
              )}
              <span className={styles.moneyAmount}>{formatMoneyDisplay(getDisplayPrice(), 2, true)}</span>
              <span className={styles.perPeriod}>per {customer.planDuration}</span>
            </div>
          </div>
          {hasDiscount && discountLabel && (
            <div className={styles.discountLabel} data-testid="discount-label">
              <span className={styles.discountText}>
                ({discountLabel}
                {customer.couponWillExpire &&
                  customer.couponDurationLabel &&
                  ` · ${customer.couponDurationLabel} remaining`}
                )
              </span>
            </div>
          )}
        </div>
      </div>

      {notFreeOrProPlan && (
        <p className={styles.subtext} data-testid="licenses-section">
          <span className={styles.bold}>{customer.seats}</span> {pluralize('license', customer.seats)} -
          <span className={styles.bold}>{formatMoneyDisplay(customer.pricePerSeat)}</span> per user/
          {customer.planDuration}
        </p>
      )}
    </div>
  )
}
