import type {QueryBuilderElement} from '@github-ui/query-builder-element'
import {FilterItem, type FilterProvider, type QueryEvent} from '@github-ui/query-builder-element/query-builder-api'
import {hasMatch} from 'fzy.js'

type ThresholdOption = {
  label: string
  value: string
}

const THRESHOLD_OPTIONS: ThresholdOption[] = [
  {label: 'All users', value: 'all'},
  {label: '1–75% of budget', value: '1-75'},
  {label: '76–89% of budget', value: '76-89'},
  {label: '90–99% of budget', value: '90-99'},
  {label: '100% (at limit)', value: '100'},
]

export class BillingBudgetThresholdFilterProvider extends EventTarget implements FilterProvider {
  type = 'filter' as const
  name: string
  priority: number
  singularItemName: string
  value: string

  constructor(
    queryBuilder: QueryBuilderElement,
    {
      name,
      value,
      priority,
    }: {
      name: string
      value: string
      priority: number
    },
  ) {
    super()

    this.name = name
    this.singularItemName = name
    this.value = value
    this.priority = priority
    queryBuilder.addEventListener('query', this)
    queryBuilder.attachProvider(this)
  }

  async handleEvent(event: QueryEvent) {
    const lastElement = event.parsedQuery.at(-1)!

    if (
      (lastElement.value !== '' || this.priority <= 5) &&
      lastElement?.type !== 'filter' &&
      !event.parsedQuery.some(e => e.type === 'filter' && e.filter === this.value) &&
      (hasMatch(lastElement?.value, this.name) || hasMatch(lastElement?.value, this.value))
    ) {
      this.dispatchEvent(new Event('show'))
    }

    if (lastElement?.type !== this.type || lastElement.filter !== this.value) return

    for (const option of THRESHOLD_OPTIONS) {
      this.emitSuggestion(option.label, option.value, lastElement.value)
    }
  }

  emitSuggestion(name: string, value: string, query: string) {
    if (query && !hasMatch(query, value) && !hasMatch(query, name)) return

    this.dispatchEvent(
      new FilterItem({
        filter: this.value,
        value,
        name,
      }),
    )
  }
}
