import {ActionList, ActionMenu} from '@primer/react'
import {useState, use} from 'react'
import {useParams} from '@github-ui/react-router'
// eslint-disable-next-line no-restricted-imports -- Error toast follows existing pattern for API failures
import {useToastContext} from '@github-ui/toast/ToastContext'

import styles from './IncludedUsageAlertsMenu.module.css'
import {updateIncludedUsageNotification} from '../../services/included-usage-notifications'
import {PageContext} from '../../App'
import {IncludedUsageTileProducts, PRODUCT_TAB_TEXT_MAP} from '../../constants'

const includedProductNames = Object.keys(IncludedUsageTileProducts).map(
  key => PRODUCT_TAB_TEXT_MAP[key as keyof typeof PRODUCT_TAB_TEXT_MAP],
)
const includedProductsDescription =
  includedProductNames.length <= 1
    ? `This includes ${includedProductNames[0] ?? ''}`
    : `This includes ${includedProductNames.slice(0, -1).join(', ')}, and ${includedProductNames[includedProductNames.length - 1]}`

interface IncludedUsageAlertsMenuProps {
  initialEnabled: boolean
  onSettingChange?: (enabled: boolean) => void
}

export default function IncludedUsageAlertsMenu({initialEnabled, onSettingChange}: IncludedUsageAlertsMenuProps) {
  const [includedUsageAlertsEnabled, setIncludedUsageAlertsEnabled] = useState(initialEnabled)
  const {isEnterpriseRoute, isOrganizationRoute} = use(PageContext)
  const params = useParams()
  const {addToast} = useToastContext()

  async function handleEnableNotification(enabled: boolean) {
    const value = enabled ? 'enabled' : 'disabled'
    const response = await updateIncludedUsageNotification({
      value,
      enterpriseSlug: isEnterpriseRoute ? params.business : undefined,
      organizationId: isOrganizationRoute ? params.organization : undefined,
    })

    if ('error' in response) {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: 'Unable to update notification setting',
        role: 'alert',
      })
      return
    }

    // Only update state on success
    setIncludedUsageAlertsEnabled(enabled)
    onSettingChange?.(enabled)
  }

  return (
    <ActionMenu>
      <ActionMenu.Button
        className={styles.actionMenuButton}
        aria-label={`Included usage alerts: ${includedUsageAlertsEnabled ? 'On' : 'Off'}`}
      >
        Included usage alerts: {includedUsageAlertsEnabled ? 'On' : 'Off'}
      </ActionMenu.Button>
      <ActionMenu.Overlay width="auto" align="start">
        <ActionList selectionVariant="single">
          <ActionList.Item selected={includedUsageAlertsEnabled} onSelect={() => handleEnableNotification(true)}>
            Turn on included usage email alerts
            <ActionList.Description variant="block">{includedProductsDescription}</ActionList.Description>
          </ActionList.Item>
          <ActionList.Item selected={!includedUsageAlertsEnabled} onSelect={() => handleEnableNotification(false)}>
            Turn off included usage email alerts
            <ActionList.Description variant="block">{includedProductsDescription}</ActionList.Description>
          </ActionList.Item>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}
