import {useState, useRef, useCallback} from 'react'
import {FormControl, Link, TextInput, Banner} from '@primer/react'
import {Dialog} from '@primer/react/experimental'

import styles from './AdditionalUsageBudgetDialog.module.css'
import {BUDGET_SCOPE_CUSTOMER, Bundles} from '../../../constants'
import {BudgetPricingTargetType, type UpsertBudgetRequest} from '../../../types/budgets'
import {BudgetLimitTypes} from '../../../enums/budgets'
import {UPSERT_BUDGET_ROUTE} from '../../../routes'
import useRoute from '../../../hooks/use-route'
import {doRequest, HTTPMethod} from '../../../hooks/use-request'
import {setBanner} from '@github-ui/page-banner'

type AdditionalUsageBudgetDialogProps = {
  budgetAmount: number
  budgetsUrl: string
  customerId: string
  budgetId?: string
  onClose: (value?: number) => void
}

function renderBanner(budgetId?: string, error?: string) {
  if (error) {
    return (
      <Banner variant="critical" title={budgetId ? 'Error updating budget' : 'Error creating budget'}>
        <Banner.Description>{error}</Banner.Description>
      </Banner>
    )
  }

  if (!budgetId) {
    return (
      <Banner title="Enable additional usage">
        <Banner.Description>Enable additional usage by setting a spending budget.</Banner.Description>
      </Banner>
    )
  }

  return null
}

export default function AdditionalUsageBudgetDialog(props: AdditionalUsageBudgetDialogProps) {
  const {budgetId, budgetAmount, budgetsUrl, customerId, onClose} = props
  const [value, setValue] = useState(budgetAmount)
  const [submitting, setSubmitting] = useState(false)
  const [error, setError] = useState('')
  const returnFocusRef = useRef<HTMLButtonElement>(null)
  const {path: editBudgetsRoute} = useRoute(UPSERT_BUDGET_ROUTE, {budgetUUID: budgetId ?? ''})
  const closeCancel = useCallback(() => onClose(), [onClose])

  const handleError = () => {
    setError(`There was an issue ${budgetId ? 'updating' : 'creating'} your budget`)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (submitting) {
      return
    }

    setSubmitting(true)

    const budgetPayload = {
      targetType: BUDGET_SCOPE_CUSTOMER,
      targetId: customerId,
      pricingTargetType: BudgetPricingTargetType.BundlePricing,
      pricingTargetId: Bundles.PremiumRequests,
      targetAmount: value,
      budgetLimitType: BudgetLimitTypes.PreventFurtherUsage,
      alertEnabled: false,
      alertRecipientUserIds: [] as string[],
    }

    try {
      const res = await doRequest<UpsertBudgetRequest>(
        budgetId ? HTTPMethod.PUT : HTTPMethod.POST,
        editBudgetsRoute,
        budgetPayload,
      )

      if (res.ok) {
        setBanner(
          <Banner
            variant="success"
            title="Updated"
            hideTitle
            description={`Budget ${budgetId ? 'updated' : 'created'} successfully`}
          />,
        )
        onClose(value)
      } else {
        handleError()
      }
    } catch {
      handleError()
    } finally {
      setSubmitting(false)
    }
  }

  return (
    <Dialog
      className={styles.dialog}
      onClose={closeCancel}
      title="Additional usage budget"
      returnFocusRef={returnFocusRef}
      width="medium"
      footerButtons={[
        {content: 'Cancel', onClick: closeCancel},
        {content: budgetId ? 'Update budget' : 'Create budget', buttonType: 'primary', onClick: handleSubmit},
      ]}
      renderFooter={({footerButtons}) => (
        <Dialog.Footer className={styles.footer}>
          <Link href={budgetsUrl} className={styles.moreOptionsLink}>
            More options
          </Link>
          <Dialog.Buttons buttons={footerButtons!} />
        </Dialog.Footer>
      )}
    >
      <div className={styles.content}>
        {renderBanner(budgetId, error)}
        <p className={styles.description}>
          Cap your maximum spend on additional pay-as-you-go usage when you run out of AI credits included with your
          plan.
        </p>
        <form onSubmit={handleSubmit}>
          <FormControl>
            <FormControl.Label>Budget amount</FormControl.Label>
            <TextInput
              leadingVisual="$"
              value={value}
              onChange={e => {
                const nextValue = Number(e.target.value)
                if (Number.isFinite(nextValue) && nextValue >= 0) {
                  setValue(nextValue)
                }
              }}
              aria-label="Budget amount in dollars"
            />
            <FormControl.Caption>Entering amount as $0 disables additional usage</FormControl.Caption>
          </FormControl>
        </form>
      </div>
    </Dialog>
  )
}
