import styles from './UsageChart.module.css'

import {LoadingComponent} from '..'
import {getPeriodText, getUsageChartTitle} from '../../utils'

import type {Filters} from '../../types/usage'

interface Props {
  copilotVariant?: boolean
  noneGroupingTitle?: string
  filters: Filters
}

export default function UsageChartSkeleton({copilotVariant, noneGroupingTitle, filters}: Props) {
  return (
    <div className={styles.skeletonContainer}>
      <div className={styles.chartHeaderContainer}>
        <div className={styles.flexGrow}>
          <h2 className={styles.chartTitle}>{getUsageChartTitle(filters, copilotVariant, {}, noneGroupingTitle)}</h2>
          <span className={styles.chartSubtitle} data-testid="usage-chart-loading-message">
            {getPeriodText(filters.period)}
          </span>
        </div>
      </div>
      <LoadingComponent className={styles.innerContainerStyle} />
    </div>
  )
}
