import {useMemo, useState} from 'react'
import {InfoIcon, SortAscIcon, SortDescIcon} from '@primer/octicons-react'

import {GROUP_BY_NONE_TYPE} from '../../../constants'
import {AIUsageUnitType, AIUsageViewMode, RequestState, UsagePeriod} from '../../../enums'
import {useCopilotUsageTableData} from '../../../hooks/usage'
import {ErrorComponent} from '../..'

import type {Filters, UsageTableData} from '../../../types/usage'
import {parseFormattedNumber} from '../../../utils/usage'
import UsageTableRowSkeleton from '../UsageTable/UsageTableRowSkeleton'
import utilitiesStyles from '../../utilities.module.css'
import tableStyles from './AIUsageTable.module.css'
import {Button} from '@primer/react'

const AI_USAGE_COLUMN_NAME_MAP: Record<string, string> = {
  'Gross amount': 'Included usage',
  'Overage spend': 'Additional usage',
}

// API returns: Model, Included credits, Additional credits, Gross amount, Overage spend
// Design wants: Model, Included credits, Included usage, Additional credits, Additional usage
const AI_USAGE_COLUMN_ORDER = [0, 1, 3, 2, 4]

function reorderAIUsageTable(table: UsageTableData): UsageTableData {
  if (table.columns.length < AI_USAGE_COLUMN_ORDER.length) return table

  const columns = AI_USAGE_COLUMN_ORDER.map(i => ({
    ...table.columns[i]!,
    name: AI_USAGE_COLUMN_NAME_MAP[table.columns[i]!.name] ?? table.columns[i]!.name,
  }))

  const rows = table.rows.map(row => ({
    ...row,
    cells: AI_USAGE_COLUMN_ORDER.map(i => row.cells[i]!),
    subtable: row.subtable,
  }))

  return {columns, rows}
}

type Props = {
  filters: Filters
  viewMode?: AIUsageViewMode
}

type SortDirection = 'asc' | 'desc'

const loadingStates = new Set<RequestState>([RequestState.INIT, RequestState.LOADING])
const isAscSort = (direction: SortDirection) => direction === 'asc'

// After reorder: Model(0), Included credits(1), Included usage(2), Additional credits(3), Additional usage(4)
const IDENTIFIER_COL = 0
const INCLUDED_CREDITS_COL = 1
const ADDITIONAL_CREDITS_COL = 3
const OVERAGE_SPEND_COL = 4

const DEFAULT_NUMERIC_HEADERS = ['Included credits', 'Included usage', 'Additional credits', 'Additional usage']

const renderSortIcon = (dir: SortDirection) => {
  if (isAscSort(dir)) {
    return <SortAscIcon size={16} className={tableStyles.userTableSortIcon} />
  }
  return <SortDescIcon size={16} className={tableStyles.userTableSortIcon} />
}

export default function AIUsageUserTable({filters, viewMode}: Props) {
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc')

  const effectiveFilters = useMemo<Filters>(() => {
    if (viewMode === AIUsageViewMode.TIME) {
      return {...filters, group: {type: GROUP_BY_NONE_TYPE, displayText: ''}}
    }
    return filters
  }, [filters, viewMode])

  const currentPage = filters.page ?? 1
  const {usageTableResponse, requestState} = useCopilotUsageTableData({
    filters: effectiveFilters,
    currentPage,
    unitType: AIUsageUnitType.AI_UNITS,
  })
  const rawTableData = usageTableResponse?.table
  const usageTableData = rawTableData ? reorderAIUsageTable(rawTableData) : rawTableData

  const sortedRows = useMemo(() => {
    const rows = usageTableData?.rows
    if (!rows || viewMode !== AIUsageViewMode.TIME || isAscSort(sortDirection)) {
      return rows
    }

    return [...rows].reverse()
  }, [usageTableData?.rows, viewMode, sortDirection])

  const filteredRows = useMemo(() => {
    if (!sortedRows) {
      return sortedRows
    }

    return sortedRows.filter(row => {
      const includedValue = row.cells[INCLUDED_CREDITS_COL]?.value
      const additionalValue = row.cells[ADDITIONAL_CREDITS_COL]?.value
      const hasIncluded = !!includedValue && Math.round(parseFormattedNumber(includedValue)) > 0
      const hasAdditional = !!additionalValue && Math.round(parseFormattedNumber(additionalValue)) > 0
      return hasIncluded || hasAdditional
    })
  }, [sortedRows])

  const periodType = filters.period?.type
  const isYearlyPeriod = periodType === UsagePeriod.THIS_YEAR || periodType === UsagePeriod.LAST_YEAR
  const firstColumnHeader = (() => {
    if (viewMode === AIUsageViewMode.TIME) {
      return isYearlyPeriod ? 'Month' : 'Date'
    }
    return 'Model'
  })()
  const ariaSortvalue = (() => {
    if (viewMode === AIUsageViewMode.TIME) {
      return isAscSort(sortDirection) ? 'ascending' : 'descending'
    }
    return 'none'
  })()

  if (requestState === RequestState.ERROR) {
    return (
      <ErrorComponent
        className={utilitiesStyles.AspectRatio3to1}
        testid="usage-loading-error"
        text="Something went wrong"
      />
    )
  }

  if (requestState === RequestState.IDLE && filteredRows?.length === 0) {
    return null
  }

  return (
    <div>
      <div className={tableStyles.usageTableBodyContainer}>
        <table className={tableStyles.userTable} data-testid="usage-table">
          <thead>
            <tr className={tableStyles.userTableHeaderRow}>
              <th className={tableStyles.userTableIdentifierHeader} aria-sort={ariaSortvalue}>
                {viewMode !== AIUsageViewMode.TIME && firstColumnHeader}
                {viewMode === AIUsageViewMode.TIME && (
                  <Button
                    className={tableStyles.sortableHeaderButton}
                    style={{marginLeft: '-12px'}}
                    variant="invisible"
                    type="button"
                    onClick={() => setSortDirection(prev => (isAscSort(prev) ? 'desc' : 'asc'))}
                    aria-label={`Sort by ${firstColumnHeader.toLowerCase()} ${isAscSort(sortDirection) ? 'descending' : 'ascending'}`}
                    data-testid="sort-date-button"
                    trailingVisual={renderSortIcon(sortDirection)}
                  >
                    {firstColumnHeader}
                  </Button>
                )}
              </th>
              {(usageTableData?.columns.slice(1) ?? DEFAULT_NUMERIC_HEADERS.map(name => ({name}))).map(col => (
                <th key={col.name} className={tableStyles.userTableNumericHeader}>
                  {col.name}
                </th>
              ))}
            </tr>
          </thead>
          <tbody data-testid="usage-table-rows">
            {loadingStates.has(requestState) && (
              <tr data-testid="usage-table-row-skeletons">
                <td colSpan={usageTableData?.columns.length ?? 5}>
                  {Array.from({length: 3}, (_, i) => (
                    <UsageTableRowSkeleton key={i} showQuantity={false} showPricePerUnit={false} />
                  ))}
                </td>
              </tr>
            )}
            {requestState === RequestState.IDLE &&
              filteredRows?.map(row => (
                <tr key={row.id} className={tableStyles.userTableRow}>
                  <td className={tableStyles.userTableIdentifierCell} data-testid="identifier-td">
                    {row.cells[IDENTIFIER_COL]?.value}
                  </td>
                  {row.cells.slice(1).map((cell, i) => (
                    <td
                      key={i}
                      className={
                        i === OVERAGE_SPEND_COL - 1 ? tableStyles.userTableSpendCell : tableStyles.userTableNumericCell
                      }
                    >
                      {cell?.value}
                    </td>
                  ))}
                </tr>
              ))}
          </tbody>
        </table>
      </div>
      <div className={tableStyles.userTableFooter}>
        <InfoIcon size={16} className={tableStyles.userTableFooterIcon} />
        <span>Each GitHub AI credit costs $0.01.</span>
      </div>
    </div>
  )
}
