import {GitHubAvatar} from '@github-ui/github-avatar'
import {Stack} from '@primer/react-brand'
import {clsx} from 'clsx'

import ColoredBullet from '../../common/ColoredBullet'

import {COLORS} from '../../../constants'
import {UsageCardVariant} from '../../../enums'
import {formatMoneyDisplay} from '../../../utils/money'

import type {RepoUsageLineItem} from '../../../types/usage'
import {PageContext} from '../../../App'
import {use} from 'react'

import styles from './UsageListTable.module.css'

interface Props {
  allOtherUsage?: number
  usage: RepoUsageLineItem[]
  variant: UsageCardVariant
}

interface TableRowProps {
  nameElement: React.ReactElement
  billedAmountElement: React.ReactElement
}

function TableRow({nameElement, billedAmountElement}: TableRowProps): React.ReactElement {
  return (
    <div className={styles.tableRow}>
      {nameElement}
      {billedAmountElement}
    </div>
  )
}

interface UsageRowItemProps {
  name: string
  amount: number
  color?: string
  avatarSrc?: string
}

function UsageRowItem({name, amount, color, avatarSrc}: UsageRowItemProps): React.ReactElement {
  return (
    <TableRow
      nameElement={
        <Stack gap="none" padding="none" direction="horizontal" alignItems="center" className="min-width-0">
          <ColoredBullet color={color ?? 'var(--borderColor-default)'} className={styles.coloredBullet} />
          {avatarSrc && <GitHubAvatar square src={avatarSrc} size={16} className={styles.avatar} />}
          <span className={styles.nameText}>{name}</span>
        </Stack>
      }
      billedAmountElement={<span className={styles.listText}>{formatMoneyDisplay(amount)}</span>}
    />
  )
}

export default function UsageListTable({usage, allOtherUsage, variant}: Props) {
  const {isEnterpriseRoute} = use(PageContext)
  const otherText = variant === UsageCardVariant.ORG ? 'All other orgs' : 'All other repositories'
  const hasOtherUsage = !!allOtherUsage && allOtherUsage > 0

  // Helper function to determine if we should hide the org segment in the repository name
  const shouldHideOrgName = (): boolean => {
    return !isEnterpriseRoute
  }

  const getName = (item: RepoUsageLineItem): string => {
    const repoName = shouldHideOrgName() ? `${item.repo.name}` : `${item.org.name}/${item.repo.name}`
    return variant === UsageCardVariant.ORG ? item.org.name : repoName
  }

  const getTableHeader = (): string => (variant === UsageCardVariant.ORG ? 'Organization' : 'Repository')

  const displayBottomBorder = (index: number): boolean => {
    if (hasOtherUsage) return true
    return index + 1 !== usage.length
  }

  return (
    <div className={styles.columnLayout}>
      <TableRow
        nameElement={<span className={styles.headerText}>{getTableHeader()}</span>}
        billedAmountElement={<span className={styles.headerAmount}>Gross amount</span>}
      />
      {usage.map((usageInformation, index) => (
        <div
          // eslint-disable-next-line @eslint-react/no-array-index-key
          key={`${getName(usageInformation)}-usage-${index}`}
          className={clsx(displayBottomBorder(index) ? styles.usageRowWithBorder : styles.usageRow)}
          data-testid={`${getName(usageInformation)}-usage-list-item`}
        >
          <UsageRowItem
            name={getName(usageInformation)}
            amount={usageInformation.billedAmount}
            color={COLORS[index]}
            avatarSrc={variant === UsageCardVariant.ORG ? usageInformation.org.avatarSrc : ''}
          />
        </div>
      ))}
      {hasOtherUsage && (
        <div data-testid="usage-list-table-other-usage" className={styles.bottomUsageRow}>
          <UsageRowItem name={otherText} amount={allOtherUsage ?? 0} />
        </div>
      )}
    </div>
  )
}
