import {use, useState} from 'react'
import {Link} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useNavigate} from '@github-ui/use-navigate'
import {OrganizationIcon, RepoIcon, GlobeIcon, CreditCardIcon, PersonIcon} from '@primer/octicons-react'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {BudgetLabel, BudgetProgressBar, BudgetWarningIcon, BudgetActionMenu} from '.'
import MultiUserBudgetListProgress from './MultiUserBudgetListProgress'
import {ResourceType} from '../../enums/cost-centers'
import {formatMoneyDisplay} from '../../utils/money'
import {BudgetPricingTargetType, type Budget} from '../../types/budgets'
import {
  BUDGET_SCOPE_ORGANIZATION,
  BUDGET_SCOPE_ENTERPRISE,
  BUDGET_SCOPE_CUSTOMER,
  BUDGET_SCOPE_REPOSITORY,
  BUDGET_SCOPE_MULTI_USER_CUSTOMER,
  BUDGET_SCOPE_USER,
  BUDGET_SCOPE_MULTI_USER_COST_CENTER,
} from '../../constants'
import {SKUs, HighWatermarkProducts, HighWatermarkSkus} from '../../constants/products'
import useRoute from '../../hooks/use-route'
import {EDIT_BUDGET_ROUTE, EDIT_COST_CENTER_ROUTE, MULTI_USER_BUDGETS_ROUTE, UPSERT_BUDGET_ROUTE} from '../../routes'
import {doRequest, HTTPMethod} from '../../hooks/use-request'
import type {Product} from '../../types/products'
import {PageContext} from '../../App'
import type {PricingDetails} from '../../types/pricings'

import styles from './BudgetData.module.css'
import {useBudgetProduct} from './hooks/use-budget-product'

interface Props {
  budgetData: Budget
  hasBudgetWritePermissions: boolean
  deleteBudget: (budgetUuid: string) => void
  enabledProducts: Product[]
  enabledSkus: PricingDetails[]
  copilotIapSubscription: boolean
  consumedCopilotLicenses?: number
  isTokenBasedBillingEnabled?: boolean
}

function IconType({type}: {type: string}) {
  if (type === BUDGET_SCOPE_ORGANIZATION) {
    return <OrganizationIcon size={16} />
  } else if ([BUDGET_SCOPE_ENTERPRISE, BUDGET_SCOPE_CUSTOMER].includes(type)) {
    return <GlobeIcon size={16} />
  } else if (type === BUDGET_SCOPE_REPOSITORY) {
    return <RepoIcon size={16} />
  } else if (type === BUDGET_SCOPE_MULTI_USER_CUSTOMER || type === BUDGET_SCOPE_MULTI_USER_COST_CENTER) {
    return <PersonIcon size={16} />
  } else if (type === BUDGET_SCOPE_USER) {
    return <PersonIcon size={16} />
  }
  return <CreditCardIcon size={16} />
}

export default function BudgetData({
  budgetData,
  hasBudgetWritePermissions,
  deleteBudget,
  enabledProducts,
  enabledSkus,
  copilotIapSubscription,
  consumedCopilotLicenses = 0,
  isTokenBasedBillingEnabled = false,
}: Props) {
  const {addToast} = useToastContext()
  const {path: editBudgetPath} = useRoute(EDIT_BUDGET_ROUTE, {budgetUUID: budgetData.uuid})
  const {path: deletePath} = useRoute(UPSERT_BUDGET_ROUTE, {budgetUUID: budgetData.uuid})
  const {path: editCostCenterPath} = useRoute(EDIT_COST_CENTER_ROUTE, {costCenterUUID: budgetData.targetId || ''})
  const {path: multiUserBudgetsPath} = useRoute(MULTI_USER_BUDGETS_ROUTE, {
    budgetUUID: budgetData.uuid,
  })
  const {isOrganizationRoute, isUserRoute} = use(PageContext)
  const isCopilotPremiumRequest = budgetData.pricingTargetId === SKUs.CopilotPremiumRequestSku
  const isMultiUserBudget =
    budgetData.targetType === BUDGET_SCOPE_MULTI_USER_CUSTOMER ||
    budgetData.targetType === BUDGET_SCOPE_MULTI_USER_COST_CENTER
  const [showIAPMessage, setShowIAPMessage] = useState(false)
  const navigate = useNavigate()

  async function handleDeleteBudget() {
    try {
      const {ok, data} = await doRequest(HTTPMethod.DELETE, deletePath, {})
      if (ok) {
        deleteBudget(budgetData.uuid)
        // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
        addToast({
          type: 'success',
          message: 'Budget deleted',
          role: 'status',
        })
      } else {
        // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
        addToast({
          type: 'error',
          message: `${data.error ? data.error : 'Unable to delete budget'}`,
          role: 'alert',
        })
      }
    } catch {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: 'Unable to delete budget',
        role: 'alert',
      })
    }
  }
  async function handleEditBudget() {
    const isZeroTargetAmount = budgetData.targetAmount === 0

    if (copilotIapSubscription && isCopilotPremiumRequest && isZeroTargetAmount) {
      setShowIAPMessage(true)
      return
    }

    navigate(editBudgetPath)
  }

  function handleViewDetails() {
    navigate(multiUserBudgetsPath)
  }

  function customerScopeLabel() {
    if (isOrganizationRoute) return 'Organization'
    if (isUserRoute) return 'Account'
    return 'Enterprise'
  }

  function fullTargetType(type: string) {
    switch (type) {
      case BUDGET_SCOPE_ORGANIZATION:
        return 'Organization'
      case BUDGET_SCOPE_REPOSITORY:
        return 'Repository'
      case BUDGET_SCOPE_ENTERPRISE:
        return 'Enterprise'
      case ResourceType.CostCenterResource:
        return 'Cost center'
      case BUDGET_SCOPE_CUSTOMER:
        return customerScopeLabel()
      case BUDGET_SCOPE_USER:
        return 'User'
      case BUDGET_SCOPE_MULTI_USER_CUSTOMER:
        return 'User • Universal'
      case BUDGET_SCOPE_MULTI_USER_COST_CENTER:
        return 'User • Cost Center'
      default:
        return ''
    }
  }

  function fallbackFriendlyName(pricingTargetId: string): string {
    return pricingTargetId
      .split('_')
      .map(word => word.charAt(0).toUpperCase() + word.slice(1))
      .join(' ')
  }

  function getFriendlyName(pricingTargetType?: BudgetPricingTargetType, pricingTargetId?: string): string {
    if (!enabledProducts || !enabledSkus || !pricingTargetId) return ''
    switch (pricingTargetType) {
      case BudgetPricingTargetType.ProductPricing: {
        return (
          enabledProducts.find(product => product.name === pricingTargetId)?.friendlyProductName ??
          fallbackFriendlyName(pricingTargetId)
        )
      }
      case BudgetPricingTargetType.SkuPricing: {
        return (
          enabledSkus.find(sku => sku.sku === pricingTargetId)?.friendlyName ?? fallbackFriendlyName(pricingTargetId)
        )
      }
      case BudgetPricingTargetType.BundlePricing: {
        if (pricingTargetId === 'premium_requests') {
          return isTokenBasedBillingEnabled ? 'All AI Credit SKUs' : 'All Premium Request SKUs'
        }
        return ''
      }
      default:
        return ''
    }
  }

  function isHighWatermarkProduct(pricingTargetType?: BudgetPricingTargetType, pricingTargetId?: string): boolean {
    if (!pricingTargetId) return false

    if (pricingTargetType === BudgetPricingTargetType.ProductPricing) {
      return (
        Object.values(HighWatermarkProducts).includes(pricingTargetId as keyof typeof HighWatermarkProducts) &&
        pricingTargetId !== HighWatermarkProducts.copilot
      )
    }

    if (pricingTargetType === BudgetPricingTargetType.SkuPricing) {
      return Object.values(HighWatermarkSkus).includes(pricingTargetId as keyof typeof HighWatermarkSkus)
    }

    return false
  }

  const shouldShowLicenseFormat = isHighWatermarkProduct(budgetData.pricingTargetType, budgetData.pricingTargetId)

  const budgetValue = budgetData.pricingTargetId
  const targetProduct = useBudgetProduct({
    budgetValue,
    enabledSkus,
    enabledProducts,
  })

  // Product-level GHAS budgets track billable licenses directly (the same count used in
  // budget alert emails via budgetState.CurrentLicenseCount), so they should report that
  // count rather than the legacy "$ consumed / price" calculation used for other products.
  const isAdvancedSecurityProductBudget =
    budgetData.pricingTargetType === BudgetPricingTargetType.ProductPricing &&
    budgetData.pricingTargetId === HighWatermarkProducts.ghas

  const shouldUseBudgetDataCurrentLicenseCount =
    targetProduct.canCreateLicenseSkuHardBudget || isAdvancedSecurityProductBudget

  const price = targetProduct.selectedBudgetProduct?.price
  // License count derived from the current amount and price, used for products
  // that do not track a license count directly (e.g. non-GHAS high watermark SKUs).
  const legacyLicenseCount = price && price > 0 ? Math.floor(budgetData.currentAmount / price) : 0

  const currentLicenseCount = shouldUseBudgetDataCurrentLicenseCount
    ? budgetData.currentLicenseCount
    : legacyLicenseCount

  const effectiveBudgetCurrentAmount = shouldUseBudgetDataCurrentLicenseCount
    ? budgetData.currentLicenseCount
    : budgetData.currentAmount
  const effectiveBudgetTargetAmount = shouldUseBudgetDataCurrentLicenseCount
    ? budgetData.licenseCount
    : budgetData.targetAmount

  const isOverBudget = effectiveBudgetCurrentAmount > effectiveBudgetTargetAmount

  // We always show budgets for Copilot Premium Requests now that the feature is enabled
  return (
    <>
      <tr key={budgetData.uuid} className={styles.BudgetRow}>
        <td className={styles.TargetCell}>
          <div className={styles.IconContainer}>
            <IconType type={budgetData.targetType} />
          </div>
          <div className={styles.TargetInfo}>
            <div className={styles.DataCell}>
              <span className={styles.TypeLabel}>
                {fullTargetType(budgetData.targetType)}
                {budgetData.excludeCostCenterUsage &&
                  [BUDGET_SCOPE_ENTERPRISE, BUDGET_SCOPE_CUSTOMER].includes(budgetData.targetType) && (
                    <>
                      {' • '}
                      <span style={{color: 'var(--fgColor-muted)'}}>Excludes cost centers</span>
                    </>
                  )}
              </span>
              {budgetData.targetType === ResourceType.CostCenterResource && !budgetData.targetName ? (
                <Link href={editCostCenterPath}>
                  {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
                  <span className={styles.LinkText}>View Details</span>
                </Link>
              ) : (
                <span className={styles.TargetName}>
                  {budgetData.targetType === BUDGET_SCOPE_MULTI_USER_CUSTOMER ? 'Universal' : budgetData.targetName}
                  {isMultiUserBudget && (
                    <>
                      {' • '}
                      <span style={{color: 'var(--fgColor-muted)', fontWeight: 'var(--base-text-weight-normal)'}}>
                        {formatMoneyDisplay(budgetData.targetAmount, 0)} per user
                      </span>
                    </>
                  )}
                </span>
              )}
            </div>
            <BudgetLabel
              budgetCurrentAmount={effectiveBudgetCurrentAmount}
              budgetTargetAmount={effectiveBudgetTargetAmount}
            />
          </div>
        </td>
        <td className={styles.PricingTypeCell}>
          <div className={styles.DataCell}>
            <span className={styles.CellLabel}>
              {budgetData.pricingTargetType === BudgetPricingTargetType.ProductPricing ? 'Product' : 'SKU'}
            </span>
            <span className={styles.CellValue}>
              {getFriendlyName(budgetData.pricingTargetType, budgetData.pricingTargetId)}
            </span>
          </div>
        </td>
        <td className={styles.StopUsageCell}>
          <div className={styles.DataCell}>
            <span className={styles.CellLabel}>Stop usage</span>
            <span className={styles.CellValue}>
              {budgetData.budgetLimitType === 'PreventFurtherUsage' ? 'Yes' : 'No'}
            </span>
          </div>
        </td>
        <td className={styles.ProgressCell}>
          <div className={styles.ProgressContainer}>
            <div className={styles.ProgressRow}>
              <div className={styles.ProgressContent}>
                {isMultiUserBudget ? (
                  <MultiUserBudgetListProgress
                    budgetThresholdsSummary={budgetData.budgetThresholdsSummary}
                    consumedCopilotLicenses={consumedCopilotLicenses}
                    budgetCurrentAmount={budgetData.currentAmount}
                  />
                ) : (
                  <>
                    <BudgetProgressBar
                      budgetCurrentAmount={effectiveBudgetCurrentAmount}
                      budgetTargetAmount={effectiveBudgetTargetAmount}
                    />
                    <div className={styles.ProgressDetails}>
                      <div>
                        <BudgetWarningIcon isOverBudget={isOverBudget} />
                        <span className={styles.LinkText}>
                          {shouldShowLicenseFormat
                            ? `${currentLicenseCount.toLocaleString()} consumed`
                            : formatMoneyDisplay(budgetData.currentAmount)}
                        </span>
                        &nbsp;
                        {!shouldShowLicenseFormat && <span className={styles.ProgressAmount}>spent</span>}
                      </div>
                      <div>
                        <span className={styles.LinkText}>
                          {shouldShowLicenseFormat
                            ? `${Math.round(budgetData.licenseCount).toLocaleString()}`
                            : formatMoneyDisplay(budgetData.targetAmount)}
                        </span>
                        &nbsp;
                        <span className={styles.ProgressAmount}>
                          {shouldShowLicenseFormat ? 'license budget' : 'budget'}
                        </span>
                      </div>
                    </div>
                  </>
                )}
              </div>
              <BudgetActionMenu
                budgetId={budgetData.uuid}
                productName={getFriendlyName(budgetData.pricingTargetType, budgetData.pricingTargetId)}
                targetType={budgetData.targetType}
                targetName={budgetData.targetName}
                onEditClick={handleEditBudget}
                onDeleteClick={handleDeleteBudget}
                onViewDetailsClick={isMultiUserBudget ? handleViewDetails : undefined}
                hasBudgetWritePermissions={hasBudgetWritePermissions}
              />
            </div>
          </div>
        </td>
      </tr>
      {showIAPMessage && (
        <tr className={styles.IAPMessageRow} data-testid="copilot-iap-error-message">
          <td className={styles.IAPMessageCell}>
            <InlineMessage variant="critical">
              Your Copilot premium request budget cannot be adjusted because your subscription was made via mobile
              in-app purchase. Manage your subscription in App Store settings.
            </InlineMessage>
          </td>
        </tr>
      )}
    </>
  )
}
