import {useMemo} from 'react'
import type {ProductSkuItem} from '../../../types/product-sku-item'

interface UseLicenseCalculationsParams {
  budgetAmount: number | string
  selectedBudgetProduct: ProductSkuItem | null
  isCopilotProduct: boolean
}

interface LicenseCalculationResult {
  budgetDollarAmount: number
  shouldShowLicenseCount: boolean
}

export function useLicenseCalculations({
  budgetAmount,
  selectedBudgetProduct,
  isCopilotProduct,
}: UseLicenseCalculationsParams): LicenseCalculationResult {
  return useMemo(() => {
    if (!selectedBudgetProduct?.price) {
      return {
        budgetDollarAmount: 0,
        shouldShowLicenseCount: false,
      }
    }

    const budgetDollarAmount = Number(budgetAmount) * selectedBudgetProduct.price

    return {
      budgetDollarAmount,
      shouldShowLicenseCount: !isCopilotProduct,
    }
  }, [budgetAmount, selectedBudgetProduct, isCopilotProduct])
}
