import {KebabHorizontalIcon, TrashIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Button, IconButton, Dialog} from '@primer/react'
import {useRef, useState} from 'react'

import styles from './CreditActionMenu.module.css'

type CreditActionMenuProps = {
  creditId: string
  scope: string
  onDeleteClick: () => void
  disabled?: boolean
}

export default function CreditActionMenu({creditId, scope, onDeleteClick, disabled = false}: CreditActionMenuProps) {
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const returnFocusRef = useRef(null)

  const onDeleteDialogOpen = () => setIsDeleteDialogOpen(true)
  const onDeleteDialogClose = () => setIsDeleteDialogOpen(false)
  const onDeleteCredit = () => {
    onDeleteClick()
    onDeleteDialogClose()
  }

  return (
    <>
      <ActionMenu>
        <ActionMenu.Anchor>
          {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
          <IconButton
            unsafeDisableTooltip
            icon={KebabHorizontalIcon}
            variant="invisible"
            aria-label={`View actions for credit ${scope}`}
            name="action-icon"
            className={styles.ActionIconButton}
          />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay>
          <ActionList>
            <ActionList.Item
              data-testid={`delete-credit-${creditId}`}
              variant={disabled ? undefined : 'danger'}
              onSelect={onDeleteDialogOpen}
              disabled={disabled}
            >
              <ActionList.LeadingVisual>
                <TrashIcon />
              </ActionList.LeadingVisual>
              Delete
            </ActionList.Item>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
      {isDeleteDialogOpen && (
        <Dialog
          aria-labelledby="delete-credit-header"
          onClose={onDeleteDialogClose}
          returnFocusRef={returnFocusRef}
          className={styles.Dialog}
        >
          <section className={styles.DialogBody}>
            <p className={styles.DialogBodyText}>
              <strong>Are you sure you want to delete the credit for {scope}?</strong>
            </p>
            <p>Once deleted, the credit will no longer exist.</p>
          </section>
          <div className={styles.DialogFooter}>
            <Button onClick={onDeleteDialogClose} className={styles.CancelButton}>
              Cancel
            </Button>
            <Button onClick={onDeleteCredit} variant="danger">
              Delete credit
            </Button>
          </div>
        </Dialog>
      )}
    </>
  )
}
