import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Link, Heading} from '@primer/react'

import type {Product} from '../../types/products'
import styles from './ProductsPage.module.css'

export interface ProductsPagePayload {
  products: Product[]
}

export const productTableStyle = {
  width: '100%',
  borderWidth: 1,
  borderStyle: 'solid',
  borderColor: 'border.default',
  borderRadius: 2,
}

export const productRowStyle = {
  p: 3,
  fontSize: 16,
  borderBottomColor: 'border.default',
  borderBottomStyle: 'solid',
}

export function ProductsPage() {
  const payload = useRoutePayload<ProductsPagePayload>()
  const {products} = payload

  const skuQueryURL = 'webevents+%7C+where+action+%3D%3D+"billing.sku_update"+or+action+%3D%3D+"billing.sku_create"'

  return (
    <div>
      <div className="Subhead">
        <Heading as="h2" className={`Subhead-heading ${styles.pageHeading}`}>
          Products
        </Heading>
      </div>
      <div className="Box tmp-mb-4 rounded-2">
        <div className={`Box d-flex flex-row flex-items-center gap-2 ${styles.auditLogBox}`}>
          <div className="flex-1 d-flex gap-2">
            {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
            <span className={styles.auditLogLabel}>Product Audit Logs</span>
          </div>
          <Link href={`/stafftools/audit_log?query=${skuQueryURL}`}>View SKU change related events</Link>
        </div>
      </div>
      {products?.length > 0 && (
        <div className={styles.productTable} data-testid="products-table">
          {products?.map((product, index) => (
            <div
              key={product.name}
              className={styles.productRow}
              style={{
                borderBottomWidth: index === products.length - 1 ? 0 : 1,
              }}
            >
              <Link href={`/stafftools/billing/products/${product.name}`}>{product.friendlyProductName}</Link>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
