import capitalize from 'lodash-es/capitalize'

import {isProductUsageLineItem, isRepoUsageLineItem} from './types'

import type {Budget} from '../types/budgets'
import {BudgetType} from '../enums/budgets'
import {HighWatermarkProducts} from '../constants'
import {UsageGrouping} from '../enums'
import {isLicensedSkuWithDailyEmissions} from './group'
import {formatMoneyDisplay} from './money'

import type {Filters, UsageLineItem} from '../types/usage'

export const findMatchingBudget = (row: UsageLineItem, budgets: Budget[], groupType: UsageGrouping): Budget | void => {
  const budget = budgets.find(b => {
    switch (groupType) {
      case UsageGrouping.ORG:
        // TODO: Verify org target type is correct
        return b.targetType === BudgetType.ORG && isRepoUsageLineItem(row) && row.org.name === b.targetName
      case UsageGrouping.REPO:
        return (
          b.targetType === BudgetType.REPO &&
          isRepoUsageLineItem(row) &&
          b.targetName === `${row.org.name}/${row.repo.name}`
        )
    }
  })

  return budget
}

export const formatQuantityDisplay = (lineItem: UsageLineItem, digits = 2): string => {
  const value = getQuantity(lineItem)
  if (!isProductUsageLineItem(lineItem)) return value.toString()

  let unit = ''
  switch (lineItem.unitType) {
    case 'Seconds':
      unit = ' sec'
      break
    case 'Minutes':
      unit = ' min'
      break
    case 'Hours':
      unit = ' hr'
      break
    case 'Bytes':
      unit = ' B'
      break
    case 'Megabytes':
      unit = ' MB'
      break
    case 'Gigabytes':
      unit = ' GB'
      break
    case 'ByteHours':
      unit = ' B-hr'
      break
    case 'MegabyteHours':
      unit = ' MB-hr'
      break
    case 'GigabyteHours':
      unit = ' GB-hr'
      break
    case 'GigabyteMonths':
      unit = ' GB-month'
      break
    case 'ComputeSeconds':
      unit = ' compute-sec'
      break
    case 'GigabyteSeconds':
      unit = ' GB-sec'
      break
    case 'TokenUnits':
      unit = ' token units'
      break
    case 'AIUnits':
      unit = ' credits'
      break
    case 'UserMonths':
      if (lineItem.dailyLicenseQuantity) {
        const roundedValue = Math.round(value)
        unit = roundedValue === 1 ? ' license' : ' licenses'
      } else unit = ' license-month'
      break
    case 'Requests':
      unit = ' requests'
      break
    default:
      unit = ''
      break
  }
  return getUnitFormatter(digits).format(value) + unit
}

// Cache one `Intl.NumberFormat` per distinct `digits` value at module scope.
// The constructor is expensive (and ~2x slower on Safari than on V8); this is
// called per row in usage tables.
const unitFormatterCache = new Map<number, Intl.NumberFormat>()

function getUnitFormatter(digits: number): Intl.NumberFormat {
  let formatter = unitFormatterCache.get(digits)
  if (!formatter) {
    formatter = new Intl.NumberFormat('en-US', {
      maximumFractionDigits: digits,
    })
    unitFormatterCache.set(digits, formatter)
  }
  return formatter
}

const getQuantity = (usage: UsageLineItem): number => {
  if (isLicensedSkuWithDailyEmissions(usage) && usage.dailyLicenseQuantity) {
    return usage.dailyLicenseQuantity
  }
  if (isProductUsageLineItem(usage) && usage.product in HighWatermarkProducts) {
    // Copilot has SKUs that are not high watermark (e.g. premium requests); only
    // show the full quantity for the license-based Copilot SKUs (UserMonths).
    if (usage.product === HighWatermarkProducts.copilot && usage.unitType !== 'UserMonths') {
      return usage.quantity
    }
    return usage.fullQuantity > 0 ? usage.fullQuantity : usage.quantity
  } else {
    return usage.quantity
  }
}

export const getBilledAmount = (totalAmount: number | null | undefined) => {
  if (typeof totalAmount === 'number') {
    return formatMoneyDisplay(totalAmount)
  } else return 'N/A'
}

/**
 * Parses a formatted number string (with commas) and returns a number
 * @param str - The formatted number string (e.g., "1,234,567")
 * @returns The parsed number or 0 if invalid
 */
export const parseFormattedNumber = (str: string): number => {
  return Number(str.replace(/,/g, '')) || 0
}

// Generated a title for the usage chart based on the current filters applied
export function getUsageChartTitle(
  filters: Filters,
  copilotVariant: boolean | undefined,
  modelsMap: Record<string, string>,
  noneGroupingTitle?: string,
): string {
  let title = copilotVariant ? 'Usage' : 'Metered usage'
  let groupByType = ''

  switch (filters.group?.type) {
    case UsageGrouping.ORG: {
      groupByType = 'organizations'
      break
    }
    case UsageGrouping.REPO: {
      groupByType = 'repositories'
      break
    }
    case UsageGrouping.SKU: {
      groupByType = 'skus'
      break
    }
    case UsageGrouping.PRODUCT: {
      groupByType = 'products'
      break
    }
    case UsageGrouping.COSTCENTER: {
      groupByType = 'cost centers'
      break
    }
    case UsageGrouping.MODEL: {
      groupByType = 'models'
      break
    }
    case UsageGrouping.USER: {
      groupByType = 'users'
      break
    }
    case UsageGrouping.NONE: {
      if (noneGroupingTitle) {
        title = noneGroupingTitle
      }
      break
    }
  }

  // Only attempt to add filter data to the title text if it exists and has a filter value
  if (filters.searchQuery && filters.searchQuery.includes(':')) {
    let queryPartsTitleText = ''
    // Split by spaces, unless those spaces are in quotation marks, which is common for cost center names
    const queryParts = filters.searchQuery.match(/(?:[^\s"]+|"[^"]*")+/g) || []

    for (const queryPart of queryParts) {
      const [groupByField, groupByValue] = queryPart.split(':')

      if (!groupByField || !groupByValue) continue

      if (['repo', 'org', 'user'].includes(groupByField)) {
        queryPartsTitleText += `${groupByValue} `
      } else if (['product', 'sku'].includes(groupByField)) {
        queryPartsTitleText += `${capitalize(groupByValue)} `
      } else if (['cost_center'].includes(groupByField)) {
        // Cost center names with spaces will be in quotation marks, remove those if present at beginning and end
        if (groupByValue.startsWith('"') && groupByValue.endsWith('"')) {
          queryPartsTitleText += `${groupByValue.split('').slice(1, -1).join('')} `
        } else {
          queryPartsTitleText += `${groupByValue} `
        }
      } else if (['model'].includes(groupByField)) {
        if (modelsMap && modelsMap[groupByValue]) {
          queryPartsTitleText += `${modelsMap[groupByValue]} `
        } else {
          queryPartsTitleText += `${groupByValue} `
        }
      }
    }

    if (queryPartsTitleText) {
      if (filters.searchQuery.includes('user:')) {
        title = `${queryPartsTitleText.trim()}'s usage`
      } else {
        title = `${queryPartsTitleText} usage`
      }
    }
  }

  if (groupByType) title += ` grouped by ${groupByType}`

  return title
}
