import {useState, useMemo} from 'react'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'

import useRequest from '../use-request'

import {BUDGETS_PAGE_SIZE} from '../../constants'
import {MULTI_USER_BUDGET_STATES_ROUTE} from '../../routes'

import type {MultiUserBudgetUserState, GetMultiUserBudgetStatesResponse} from '../../types/budgets'
import {RequestState} from '../../enums'

const MULTI_USER_BUDGET_STATES_ERROR = 'Unable to load user budget data'

interface UseMultiUserBudgetStatesProps {
  budgetUUID: string
  page?: number
  pageSize?: number
  sortOrder?: 'descending' | 'ascending'
  username?: string
  thresholdLowerBound?: number
  thresholdUpperBound?: number
  noop?: boolean
}

interface UseMultiUserBudgetStatesReturn {
  userStates: MultiUserBudgetUserState[]
  totalCount: number
  hasNextPage: boolean
  requestState: RequestState
}

/**
 * Hook to fetch paginated per-user budget states for a multi-user budget.
 * Makes a client-side JSON request so data loads after the page renders.
 */
export default function useMultiUserBudgetStates({
  budgetUUID,
  page = 1,
  pageSize = BUDGETS_PAGE_SIZE,
  sortOrder = 'descending',
  username = '',
  thresholdLowerBound,
  thresholdUpperBound,
  noop = false,
}: UseMultiUserBudgetStatesProps): UseMultiUserBudgetStatesReturn {
  const [userStates, setUserStates] = useState<MultiUserBudgetUserState[]>([])
  const [totalCount, setTotalCount] = useState(0)
  const [hasNextPage, setHasNextPage] = useState(false)
  const [requestState, setRequestState] = useState<RequestState>(noop ? RequestState.IDLE : RequestState.INIT)
  const {addToast} = useToastContext()

  const sortOrderValue = sortOrder === 'ascending' ? '1' : '0'

  const reqParams = useMemo(() => {
    const params: Record<string, string> = {
      budget_uuid: budgetUUID,
      page: String(page),
      page_size: String(pageSize),
      sort_order: sortOrderValue,
    }
    if (username) {
      params.username = username
    }
    if (thresholdLowerBound !== undefined) {
      params.threshold_lower_bound = String(thresholdLowerBound)
    }
    if (thresholdUpperBound !== undefined) {
      params.threshold_upper_bound = String(thresholdUpperBound)
    }
    return params
  }, [budgetUUID, page, pageSize, sortOrderValue, username, thresholdLowerBound, thresholdUpperBound])

  useRequest({
    route: MULTI_USER_BUDGET_STATES_ROUTE,
    reqParams,
    noop,
    onStart: () => {
      setRequestState(RequestState.LOADING)
    },
    onSuccess: response => {
      const payload = response.data.payload as GetMultiUserBudgetStatesResponse

      if (!Array.isArray(payload.user_states)) {
        // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
        addToast({
          type: 'error',
          message: MULTI_USER_BUDGET_STATES_ERROR,
        })
        setRequestState(RequestState.ERROR)
        return
      }

      setUserStates(payload.user_states)
      setTotalCount(payload.total_count ?? 0)
      setHasNextPage(payload.has_next_page ?? false)
      setRequestState(RequestState.IDLE)
    },
    onError: () => {
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: MULTI_USER_BUDGET_STATES_ERROR,
      })
      setRequestState(RequestState.ERROR)
    },
  })

  return {
    userStates,
    totalCount,
    hasNextPage,
    requestState,
  }
}
