import {useState} from 'react'
import useRequest from '../use-request'
import {COPILOT_USAGE_CARD_DATA_ROUTE} from '../../routes'

import {ERRORS} from '../../constants'
import {AIUsageUnitType, RequestState, UsagePeriod} from '../../enums'

import type {Filters} from '../../types/usage'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'

export interface AIUsageCardData {
  includedCreditsUsed: number
  includedCreditsEntitlement: number
  overageSpend: number
  netQuantity: number
}

type UseAIUsageCardDataParams = {
  filters: Filters
  noop?: boolean
  unitType?: AIUsageUnitType
}

function useAIUsageCardData({filters, noop = false, unitType = AIUsageUnitType.AI_UNITS}: UseAIUsageCardDataParams) {
  const defaultData: AIUsageCardData = {
    includedCreditsUsed: 0,
    includedCreditsEntitlement: 0,
    overageSpend: 0,
    netQuantity: 0,
  }

  const [usageCardData, setUsageCardData] = useState<AIUsageCardData>(defaultData)
  const [requestState, setRequestState] = useState<RequestState>(RequestState.INIT)
  const {addToast} = useToastContext()

  useRequest({
    route: COPILOT_USAGE_CARD_DATA_ROUTE,
    reqParams: {
      customer_id: filters.customer.id,
      period: (filters.period?.type ?? UsagePeriod.DEFAULT).toString(),
      query: filters.searchQuery,
      unit_type: unitType.toString(),
    },
    noop,
    onStart: () => {
      setUsageCardData(defaultData)
      setRequestState(RequestState.LOADING)
    },
    onSuccess: response => {
      setUsageCardData({
        includedCreditsUsed: response.data.includedCreditsUsed ?? 0,
        includedCreditsEntitlement: response.data.includedCreditsEntitlement ?? 0,
        overageSpend: response.data.overageSpend ?? 0,
        netQuantity: response.data.netQuantity ?? 0,
      })
      setRequestState(RequestState.IDLE)
    },
    onError: () => {
      setRequestState(RequestState.ERROR)
      // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
      addToast({
        type: 'error',
        message: ERRORS.QUERY_USAGE_ERROR,
      })
    },
  })

  if (noop) {
    return {usageCardData: defaultData, requestState: RequestState.IDLE}
  }

  return {usageCardData, requestState}
}

export default useAIUsageCardData
