import {use} from 'react'
import {Link} from '@primer/react'

import {PageContext} from '../../../App'
import AIUsageSummaryCard from './AIUsageSummaryCard'
import CfiSummaryCards from './CfiSummaryCards'
import styles from './AIUsageSummaryCardContainer.module.css'
import {formatMoneyDisplay} from '../../../utils/money'
import useRoute from '../../../hooks/use-route'
import useAIUsageCardData from '../../../hooks/usage/use-ai-usage-card-data'
import {
  BUDGETS_ROUTE,
  COPILOT_MANAGE_POLICIES_BASE_ROUTE_ENT,
  COPILOT_MANAGE_POLICIES_BASE_ROUTE_ORGS,
} from '../../../routes'
import {UsagePeriod} from '../../../enums'

import type {CfiQuota, Filters} from '../../../types/usage'

interface Props {
  filters: Filters
  overageEnabled?: boolean
  cfiQuota?: CfiQuota
}

export default function AIUsageSummaryCardContainer({filters, overageEnabled, cfiQuota}: Props) {
  const {isEnterpriseRoute, isOrganizationRoute, isStafftoolsUserRoute} = use(PageContext)
  const {path: budgetsUrl} = useRoute(BUDGETS_ROUTE)
  const {path: enterprisePolicyPath} = useRoute(COPILOT_MANAGE_POLICIES_BASE_ROUTE_ENT)
  const {path: orgPolicyPath} = useRoute(COPILOT_MANAGE_POLICIES_BASE_ROUTE_ORGS)
  const policyUrl = isOrganizationRoute ? orgPolicyPath : isEnterpriseRoute ? enterprisePolicyPath : undefined

  // isUserRoute from the page context returns true for organizations in stafftools as well
  // since they share the same base route. Checking that it's not an enterprise or organization route
  // allows stafftools to properly show organization specific content at the expense of user specific content.
  const isUserRoute = !isEnterpriseRoute && !isOrganizationRoute
  const userSearchQueryPresent = filters.searchQuery.includes('user:')

  // cfiQuota is only present for individual consumptive users, which lets us distinguish
  // stafftools individual user pages from stafftools org pages (both share /stafftools/users/).
  const isCfiUserRoute = isUserRoute || isStafftoolsUserRoute
  const {usageCardData, requestState} = useAIUsageCardData({
    filters,
    noop: isCfiUserRoute && !!cfiQuota,
  })
  const {includedCreditsEntitlement, includedCreditsUsed, overageSpend} = usageCardData

  if (isCfiUserRoute && cfiQuota) {
    const {overage, limits} = cfiQuota
    const {entitlement, entitlement_used, reset_label} = limits

    return (
      <CfiSummaryCards
        overage={overage}
        resetLabel={reset_label}
        creditsEntitlement={entitlement}
        creditsUsed={entitlement_used}
        budgetsUrl={isStafftoolsUserRoute ? '' : budgetsUrl}
      />
    )
  }

  const getDaysUntilReset = () => {
    const now = new Date()
    const nextMonth = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1))
    const timeDiff = nextMonth.getTime() - now.getTime()
    const daysRemaining = Math.ceil(timeDiff / (1000 * 3600 * 24))

    return daysRemaining === 1 ? '1 day' : `${daysRemaining} days`
  }

  // the reset date is currently always going to be the first of the month
  // this would change if we ever decide to reset based on the bill cycle days https://github.com/github/copilot/issues/20177
  const getResetDate = () => {
    const now = new Date()
    return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 1, 1))
  }

  const formattedResetDate = getResetDate().toLocaleDateString('default', {
    timeZone: 'UTC',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  })

  const overageSpendDescription = overageEnabled
    ? 'Spend on additional AI credits exceeding your included credits.'
    : isOrganizationRoute
      ? 'If enabled, your organization will be billed for additional AI credits usage after your included credits have been exhausted.'
      : 'If enabled, your enterprise will be billed for additional AI credits usage after your included credits have been exhausted.'

  const getMonthlyResetText = (isCurrentMonth: boolean, usePlural = true) => {
    if (!isCurrentMonth) return ''
    const limitText = usePlural ? 'limits reset' : 'limit resets'
    return ` Monthly ${limitText} in ${getDaysUntilReset()} on ${formattedResetDate}.`
  }

  const includedUsageCardDescription = () => {
    const isCurrentMonth = filters.period?.type === UsagePeriod.THIS_MONTH

    const baseText = userSearchQueryPresent
      ? 'Included AI credits consumed by selected Copilot user'
      : 'Included AI credits consumed by Copilot users in your account'

    return `${baseText}.${getMonthlyResetText(isCurrentMonth, false)}`
  }

  return (
    <div className={styles.summaryCardsGrid}>
      {!isUserRoute && (
        <AIUsageSummaryCard
          title="Included credits"
          value={includedCreditsUsed}
          description={includedUsageCardDescription()}
          testId="included-ai-usage-card"
          requestState={requestState}
          showProgressBar
          entitlementValue={includedCreditsEntitlement}
          variant="ai-usage"
        />
      )}
      <AIUsageSummaryCard
        title={
          <>
            <span>Additional usage</span>
            {overageEnabled ? (
              <Link className="ml-auto" href={budgetsUrl}>
                Edit budget
              </Link>
            ) : (
              policyUrl && (
                <Link className="ml-auto" href={policyUrl}>
                  Enable additional usage
                </Link>
              )
            )}
          </>
        }
        value={overageEnabled ? formatMoneyDisplay(overageSpend, 2, true) : 'Not enabled'}
        description={overageSpendDescription}
        testId="overage-spend-card"
        requestState={requestState}
        variant="ai-usage"
      />
    </div>
  )
}
