import {useState, useRef} from 'react'
import {Button} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {formatMoneyDisplay} from '../../utils/money'
import styles from './UsageOverviewListDialog.module.css'

interface Props {
  totalUsage: number
  usageMap: Record<string, number>
}

export default function UsageOverviewListDialog({totalUsage, usageMap}: Props) {
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const returnFocusRef = useRef(null)

  return (
    <div data-testid="usage-overview-list-dialog-container">
      <Button variant="invisible" size="small" alignContent="center" onClick={() => setIsDialogOpen(true)}>
        More details
      </Button>

      {isDialogOpen && (
        <Dialog
          onClose={() => setIsDialogOpen(false)}
          title="Current metered usage"
          returnFocusRef={returnFocusRef}
          aria-labelledby="header"
          className={styles.dialog}
        >
          <div className={styles.container}>
            <div>
              <span className={styles.totalUsage} data-testid="total-usage">
                {formatMoneyDisplay(totalUsage)}
              </span>
            </div>
            <ul className="mt-0 pt-0">
              {Object.entries(usageMap)
                .sort(([, valueA], [, valueB]) => valueB - valueA)
                .map(([key, value]) => {
                  return (
                    <li
                      className={styles.listItem}
                      key={`usage-selection-${key}`}
                      data-testid={`usage-selection-${key}`}
                    >
                      <p className={styles.listItemLabel}>{key}</p>
                      <p className={styles.listItemValue}>{formatMoneyDisplay(value || 0)}</p>
                    </li>
                  )
                })}
            </ul>
          </div>
        </Dialog>
      )}
    </div>
  )
}
