import {AlertIcon} from '@primer/octicons-react'
import {Heading} from '@primer/react'

import styles from './NoDataComponent.module.css'

interface Props {
  testid: string
  text: string
  className?: string
}

export default function NoDataComponent({testid, text, className}: Props) {
  return (
    <div className={`${styles.Container} ${className || ''}`}>
      <AlertIcon size={32} className={styles.Icon} />
      <Heading as="h2" className={styles.Heading} data-testid={testid}>
        {text}
      </Heading>
    </div>
  )
}
