import type {ReactNode} from 'react'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'

import styles from './LoadingComponent.module.css'

interface Props {
  children?: ReactNode
  className?: string
  testid?: string
}

export default function LoadingComponent({children, className, testid}: Props) {
  return (
    <div className={`${styles.containerStyle} ${className}`} data-testid={testid}>
      {children ? children : <LoadingSkeleton width="100%" height="100%" variant="rounded" />}
    </div>
  )
}
