import {UsagePeriod} from '../enums'

/**
 * Returns true if the selected usage period falls entirely before the TBB launch date,
 * meaning no AI credit data would be available for that period.
 *
 * This utility and its call sites (e.g. AIUsagePreLaunchEmptyState) can be removed after
 * January 2027. By then, the "Last year" period will contain partial post-launch
 * data (launch date: June 1, 2026), so no period will be entirely before launch.
 */
export function isPeriodBeforeLaunch(periodType: UsagePeriod, launchDate: Date, now: Date = new Date()): boolean {
  switch (periodType) {
    case UsagePeriod.LAST_MONTH: {
      // Empty state if the entire last month is before launch
      // Use start of current month (end-exclusive) to avoid off-by-one when launch is mid-day on the last day
      const startOfThisMonth = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1))
      return startOfThisMonth <= launchDate
    }
    case UsagePeriod.LAST_YEAR: {
      // Empty state if all of last year is before launch
      // Use start of current year (end-exclusive) to avoid off-by-one when launch is mid-day on Dec 31
      const startOfThisYear = new Date(Date.UTC(now.getUTCFullYear(), 0, 1))
      return startOfThisYear <= launchDate
    }
    case UsagePeriod.THIS_MONTH:
    case UsagePeriod.THIS_YEAR:
    case UsagePeriod.DEFAULT:
      // Current/default periods are not entirely before launch, so never show pre-launch empty state.
      return false
    default:
      // Fallback for any unexpected future or invalid usage period values.
      return false
  }
}
