import {KebabHorizontalIcon, PencilIcon, TrashIcon, EyeIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Dialog, IconButton} from '@primer/react'
import {useRef, useState} from 'react'

import styles from './BudgetActionMenu.module.css'

type BudgetActionMenuProps = {
  budgetId: string
  productName: string
  targetType: string
  targetName: string
  onEditClick: () => void
  onDeleteClick: () => void
  onViewDetailsClick?: () => void
  hasBudgetWritePermissions: boolean
}

export default function BudgetActionMenu({
  budgetId,
  productName,
  targetType,
  targetName,
  onEditClick,
  onDeleteClick,
  onViewDetailsClick,
  hasBudgetWritePermissions,
}: BudgetActionMenuProps) {
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false)
  const returnFocusRef = useRef(null)

  const onDeleteDialogOpen = () => setIsDeleteDialogOpen(true)
  const onDeleteDialogClose = () => setIsDeleteDialogOpen(false)
  const onDeleteBudget = () => {
    onDeleteClick()
    onDeleteDialogClose()
  }

  const hasAnyAction = hasBudgetWritePermissions || !!onViewDetailsClick

  if (!hasAnyAction) {
    return <span className={styles.ActionPlaceholder} />
  }

  return (
    <>
      <ActionMenu>
        <ActionMenu.Anchor>
          {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
          <IconButton
            unsafeDisableTooltip
            icon={KebabHorizontalIcon}
            variant="invisible"
            aria-label={`View actions for ${targetType} ${targetName}'s budget`}
            name="action-icon"
            className={styles.ActionIcon}
          />
        </ActionMenu.Anchor>
        <ActionMenu.Overlay>
          <ActionList>
            {onViewDetailsClick && (
              <ActionList.Item onSelect={onViewDetailsClick}>
                <ActionList.LeadingVisual>
                  <EyeIcon />
                </ActionList.LeadingVisual>
                View details
              </ActionList.Item>
            )}
            {hasBudgetWritePermissions && (
              <ActionList.Item onSelect={onEditClick}>
                <ActionList.LeadingVisual>
                  <PencilIcon />
                </ActionList.LeadingVisual>
                Edit
              </ActionList.Item>
            )}
            {hasBudgetWritePermissions && (
              <ActionList.Item data-testid={`delete-budget-${budgetId}`} variant="danger" onSelect={onDeleteDialogOpen}>
                <ActionList.LeadingVisual>
                  <TrashIcon />
                </ActionList.LeadingVisual>
                Delete
              </ActionList.Item>
            )}
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>
      {isDeleteDialogOpen && (
        <Dialog
          aria-labelledby="delete-budget-header"
          onClose={onDeleteDialogClose}
          returnFocusRef={returnFocusRef}
          className={styles.Dialog}
          title="Delete budget"
          footerButtons={[
            {buttonType: 'default', content: 'Cancel', onClick: onDeleteDialogClose},
            {buttonType: 'danger', content: 'Delete budget', onClick: onDeleteBudget},
          ]}
        >
          <div>
            <p className={styles.DialogText}>
              <strong>
                Are you sure you want to delete the {productName} budget for {targetName}?
              </strong>
            </p>
            <p>Once deleted, the budget will no longer exist and unlimited usage will be allowed.</p>
          </div>
        </Dialog>
      )}
    </>
  )
}
