// `Intl.NumberFormat` construction is one of the most expensive Intl operations
// (especially on Safari, where it is ~2x slower than V8). `formatMoneyDisplay`
// is called per row in usage / budget / cost-center tables, so we cache one
// formatter instance per distinct `digits` value at module scope.
const currencyFormatterCache = new Map<number, Intl.NumberFormat>()

function getCurrencyFormatter(digits: number): Intl.NumberFormat {
  let formatter = currencyFormatterCache.get(digits)
  if (!formatter) {
    formatter = new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: digits,
    })
    currencyFormatterCache.set(digits, formatter)
  }
  return formatter
}

export const formatMoneyDisplay = (value: number, digits = 2, forceFormattingForZero = false): string => {
  const formatter = getCurrencyFormatter(digits)

  let formattedValue

  if (value === 0) {
    formattedValue = forceFormattingForZero ? formatter.format(value) : '$0'
  } else if (0 < value && value < 0.01 && digits === 2) {
    formattedValue = '<$0.01'
  } else {
    formattedValue = formatter.format(value)
  }
  return formattedValue
}

export function parseMoneyString(money: string | undefined): number {
  if (!money || money === 'N/A') return 0
  const parsed = parseFloat(money.replace(/[^0-9.-]/g, ''))
  return Number.isNaN(parsed) ? 0 : parsed
}
