import {deriveSegments} from '../../utils/derive-budget-segments'
import type {BudgetThresholdsSummary} from '../../types/budgets'

import styles from './MultiUserBudgetListProgress.module.css'

interface Props {
  budgetThresholdsSummary?: BudgetThresholdsSummary
  consumedCopilotLicenses: number
  budgetCurrentAmount?: number
}

/**
 * Compute the summary label for the left side below the progress bar.
 * Priority: at budget > close to budget > used budget (any non-zero usage)
 */
function getSummaryLabel(
  segments: {belowThreshold: number; nearLimit: number; atOrAboveLimit: number},
  hasAnyUsage: boolean,
): string {
  if (segments.atOrAboveLimit > 0) {
    return `${segments.atOrAboveLimit} at budget`
  }
  if (segments.nearLimit > 0) {
    return `${segments.nearLimit} close to budget`
  }
  const usedAny = segments.belowThreshold + segments.nearLimit + segments.atOrAboveLimit
  if (usedAny > 0) {
    return `${usedAny} used budget`
  }
  // Users below 75% aren't in any threshold bucket but have usage
  if (hasAnyUsage) {
    return 'used budget'
  }
  return ''
}

/**
 * Compact progress bar for the multi-user budget row on the budgets list page.
 * Shows segmented usage distribution and a summary label.
 */
export default function MultiUserBudgetListProgress({
  budgetThresholdsSummary,
  consumedCopilotLicenses,
  budgetCurrentAmount = 0,
}: Props) {
  const segments = deriveSegments(consumedCopilotLicenses, budgetThresholdsSummary)

  // Use consumedCopilotLicenses when available, otherwise derive from the threshold summary itself
  const thresholdTotal = segments.noUsage + segments.belowThreshold + segments.nearLimit + segments.atOrAboveLimit
  const totalUsers = consumedCopilotLicenses > 0 ? consumedCopilotLicenses : thresholdTotal

  const belowPct = totalUsers > 0 ? (segments.belowThreshold / totalUsers) * 100 : 0
  const nearPct = totalUsers > 0 ? (segments.nearLimit / totalUsers) * 100 : 0
  const atOrAbovePct = totalUsers > 0 ? (segments.atOrAboveLimit / totalUsers) * 100 : 0
  const noUsagePct = totalUsers > 0 ? (segments.noUsage / totalUsers) * 100 : 0

  const summaryLabel = getSummaryLabel(segments, budgetCurrentAmount > 0)

  const hasNoUsage = totalUsers > 0 && noUsagePct === 100

  if (hasNoUsage) {
    return (
      <div>
        <div className={styles.progressBar} role="img" aria-label="Budget usage distribution" />
        <div className={styles.details}>
          <span className={styles.detailLabel}>No budget usage yet</span>
          <div>
            <span className={styles.detailCount}>{totalUsers.toLocaleString()}</span>{' '}
            <span className={styles.detailLabel}>total users</span>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div>
      <div className={styles.progressBar} role="img" aria-label="Budget usage distribution">
        {belowPct > 0 && (
          <div
            className={`${styles.progressSegment} ${styles.segmentBelowThreshold}`}
            style={{width: `${belowPct}%`}}
            data-testid="segment-below-threshold"
          />
        )}
        {nearPct > 0 && (
          <div
            className={`${styles.progressSegment} ${styles.segmentNearLimit}`}
            style={{width: `${nearPct}%`}}
            data-testid="segment-near-limit"
          />
        )}
        {atOrAbovePct > 0 && (
          <div
            className={`${styles.progressSegment} ${styles.segmentAtOrAboveLimit}`}
            style={{width: `${atOrAbovePct}%`}}
            data-testid="segment-at-or-above-limit"
          />
        )}
        {noUsagePct > 0 && (
          <div
            className={`${styles.progressSegment} ${styles.segmentNoUsage}`}
            style={{width: `${noUsagePct}%`}}
            data-testid="segment-no-usage"
          />
        )}
      </div>
      <div className={styles.details}>
        <div>
          {summaryLabel && (
            <>
              <span className={styles.detailCount}>{summaryLabel.split(' ')[0]}</span>{' '}
              <span className={styles.detailLabel}>{summaryLabel.split(' ').slice(1).join(' ')}</span>
            </>
          )}
        </div>
        <div>
          <span className={styles.detailCount}>{totalUsers.toLocaleString()}</span>{' '}
          <span className={styles.detailLabel}>total users</span>
        </div>
      </div>
    </div>
  )
}
