import {TriangleDownIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Heading, IconButton} from '@primer/react'
import {clsx} from 'clsx'

import type {CustomerSelection} from '../../types/usage'
import styles from './CostCenterSelector.module.css'

interface CostCenterSelectorProps {
  selections: CustomerSelection[]
  selectedCustomer: CustomerSelection
  setSelectedCustomer: (selectedCustomer: CustomerSelection) => void
  getHeadingText?: (selectedCustomer: CustomerSelection) => string
  className?: string
  as?: 'h1' | 'h2' | 'h3' | 'h4' | 'h5' | 'h6'
  title?: string
}

export default function CostCenterSelector({
  selections,
  selectedCustomer,
  setSelectedCustomer,
  getHeadingText,
  title,
  className,
  as,
}: CostCenterSelectorProps) {
  return (
    <div className={clsx(styles.container, className)}>
      <Heading as={as ?? 'h3'} className={styles.heading}>
        {getHeadingText ? getHeadingText(selectedCustomer) : selectedCustomer.displayText}
      </Heading>
      {selections.length > 1 && (
        <ActionMenu>
          <ActionMenu.Anchor>
            {/* eslint-disable-next-line primer-react/a11y-remove-disable-tooltip */}
            <IconButton unsafeDisableTooltip icon={TriangleDownIcon} aria-label="Change cost center selection" />
          </ActionMenu.Anchor>
          <ActionMenu.Overlay>
            <ActionList selectionVariant="single" showDividers>
              <ActionList.Group>
                <ActionList.GroupHeading>{title}</ActionList.GroupHeading>
                {selections.map(selection => {
                  return (
                    <ActionList.Item
                      key={selection.id}
                      onSelect={() => setSelectedCustomer(selection)}
                      selected={selection.id === selectedCustomer.id}
                      className={styles.actionItem}
                    >
                      {selection.displayText}
                    </ActionList.Item>
                  )
                })}
              </ActionList.Group>
            </ActionList>
          </ActionMenu.Overlay>
        </ActionMenu>
      )}
    </div>
  )
}
