import {useCallback, useRef, useState, use, useMemo, useEffect} from 'react'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useSearchParams} from '@github-ui/use-navigate'
import {updateUrl} from '@github-ui/history'
import {Breadcrumbs, Button} from '@primer/react'
import {PencilIcon} from '@primer/octicons-react'

import Layout from '../components/Layout'
import MultiUserBudgetStatesTable from '../components/budget/MultiUserBudgetStatesTable'
import MultiUserBudgetOverview from '../components/budget/MultiUserBudgetOverview'
import MultiUserBudgetSearchBar from '../components/budget/MultiUserBudgetSearchBar'
import {GetUsageReportDialog} from '../components/usage'
import {PageContext} from '../App'
import useRoute from '../hooks/use-route'
import useMultiUserBudgetStates from '../hooks/budget/use-multi-user-budget-states'
import {BUDGETS_ROUTE, EDIT_BUDGET_ROUTE, NEW_BUDGET_ROUTE, PREMIUM_REQUESTS_USAGE_ROUTE} from '../routes'
import {BUDGETS_PAGE_SIZE, getBudgetTypeText, OWNER, BILLING_MANAGER, ENTERPRISE_ORG_OWNER} from '../constants'
import {parseMultiUserBudgetQuery} from '../utils/parse-multi-user-budget-query'

import type {Budget, BudgetThresholdsSummary} from '../types/budgets'
import type {AdminRole, Customer} from '../types/common'
import type {ReportTypeSelection} from '../types/usage'

import styles from './MultiUserBudgetsPage.module.css'
import {formatMoneyDisplay} from '../utils'

export interface MultiUserBudgetsPagePayload {
  budget: Budget
  customer: Customer
  consumedCopilotLicenses: number
  budgetThresholdsSummary?: BudgetThresholdsSummary
  adminRoles?: AdminRole[]
  current_user_email?: string
  disable_usage_reports?: boolean
  min_custom_date?: string
  report_type_selections?: ReportTypeSelection[]
  is_token_based_billing_enabled?: boolean
}

export function MultiUserBudgetsPage() {
  const payload = useRoutePayload<MultiUserBudgetsPagePayload>()
  const {
    budget,
    customer,
    consumedCopilotLicenses = 0,
    budgetThresholdsSummary,
    adminRoles = [],
    current_user_email: currentUserEmail,
    disable_usage_reports: disableUsageReports = false,
    min_custom_date: minCustomDate = '',
    report_type_selections: reportTypeSelections = [],
    is_token_based_billing_enabled: isTokenBasedBillingEnabled = false,
  } = payload

  const isAdmin = adminRoles.includes(OWNER) || adminRoles.includes(BILLING_MANAGER)
  const isEnterpriseOrgAdmin = !isAdmin && adminRoles.includes(ENTERPRISE_ORG_OWNER)
  const {isStafftoolsRoute} = use(PageContext)
  const canEdit = isAdmin && !isStafftoolsRoute
  const canViewUsageReport = isAdmin || isStafftoolsRoute
  const {path: budgetsPath} = useRoute(BUDGETS_ROUTE)
  const {path: analyticsPath} = useRoute(PREMIUM_REQUESTS_USAGE_ROUTE)
  const {path: editBudgetPath} = useRoute(EDIT_BUDGET_ROUTE, {budgetUUID: budget.uuid})
  const {path: newBudgetPath} = useRoute(NEW_BUDGET_ROUTE)
  const editBudgetPathTemplate = useRoute(EDIT_BUDGET_ROUTE, {budgetUUID: 'BUDGET_UUID_PLACEHOLDER'})
  const editBudgetPathFor = (budgetUUID: string) =>
    editBudgetPathTemplate.path.replace('BUDGET_UUID_PLACEHOLDER', budgetUUID)

  const [searchParams] = useSearchParams()
  const initialQuery = searchParams.get('query') ?? ''
  const pageParam = searchParams.get('page')
  const parsedPage = pageParam ? Number.parseInt(pageParam, 10) : NaN
  const initialPage = Number.isFinite(parsedPage) && parsedPage > 0 ? parsedPage : 1

  const [currentPage, setCurrentPage] = useState(initialPage)
  const [searchQuery, setSearchQuery] = useState(initialQuery)
  const [sortOrder, setSortOrder] = useState<'ascending' | 'descending'>('descending')
  const tableRef = useRef<HTMLDivElement>(null)

  const filters = useMemo(() => parseMultiUserBudgetQuery(searchQuery), [searchQuery])

  useEffect(() => {
    const params = new URLSearchParams()
    if (searchQuery) params.set('query', searchQuery)
    if (currentPage > 1) params.set('page', String(currentPage))
    const queryString = params.toString()
    updateUrl(queryString ? `?${queryString}` : window.location.pathname)
  }, [searchQuery, currentPage])

  const {userStates, totalCount, hasNextPage, requestState} = useMultiUserBudgetStates({
    budgetUUID: budget.uuid,
    page: currentPage,
    pageSize: BUDGETS_PAGE_SIZE,
    sortOrder,
    username: filters.username,
    thresholdLowerBound: filters.thresholdLowerBound,
    thresholdUpperBound: filters.thresholdUpperBound,
  })

  const handlePageChange = useCallback(
    (page: number) => {
      setCurrentPage(page)
      tableRef.current?.scrollIntoView({behavior: 'smooth', block: 'start'})
    },
    [setCurrentPage],
  )

  const handleSearchQueryChange = useCallback(
    (query: string) => {
      setSearchQuery(query)
      setCurrentPage(1)
    },
    [setSearchQuery, setCurrentPage],
  )

  const handleSortChange = useCallback(
    (direction: 'ascending' | 'descending') => {
      setSortOrder(direction)
      setCurrentPage(1)
    },
    [setSortOrder, setCurrentPage],
  )

  const pageTitle = `${getBudgetTypeText(budget.pricingTargetId, isTokenBasedBillingEnabled)} user budgets • ${formatMoneyDisplay(budget.targetAmount)}`

  return (
    <Layout>
      <GetUsageReportDialog>
        <GetUsageReportDialog.Notifications />
        <nav className={styles.breadcrumbs}>
          <Breadcrumbs>
            <Breadcrumbs.Item href={budgetsPath}>Budgets and alerts</Breadcrumbs.Item>
            <Breadcrumbs.Item selected>User budgets</Breadcrumbs.Item>
          </Breadcrumbs>
        </nav>
        <header className={`Subhead ${styles.pageHeader}`}>
          <h2 className={`Subhead-heading ${styles.pageHeading}`}>{pageTitle}</h2>
          <div className={styles.headerActions}>
            {canViewUsageReport && currentUserEmail && (
              <span className={styles.boldButton}>
                <GetUsageReportDialog.Trigger
                  currentUserEmail={currentUserEmail}
                  disableUsageReports={disableUsageReports}
                  minCustomDate={minCustomDate}
                  reportTypeSelections={reportTypeSelections}
                  premiumRequestVariant
                  isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
                />
              </span>
            )}
            {canEdit && (
              <Button as="a" href={editBudgetPath} leadingVisual={PencilIcon}>
                Edit budget
              </Button>
            )}
          </div>
        </header>
      </GetUsageReportDialog>

      <div className={styles.tableControls}>
        <MultiUserBudgetSearchBar
          customerDisplayId={customer.displayId}
          searchQuery={searchQuery}
          setSearchQuery={handleSearchQueryChange}
          isEnterpriseOrgAdmin={isEnterpriseOrgAdmin}
        />
      </div>

      <MultiUserBudgetOverview
        consumedCopilotLicenses={consumedCopilotLicenses}
        budgetThresholdsSummary={budgetThresholdsSummary}
        analyticsPath={analyticsPath}
      />

      <div ref={tableRef}>
        <MultiUserBudgetStatesTable
          userStates={userStates}
          customerId={customer.customerId}
          budget={budget}
          requestState={requestState}
          currentPage={currentPage}
          onPageChange={handlePageChange}
          hasNextPage={hasNextPage}
          totalCount={totalCount}
          newBudgetPath={newBudgetPath}
          editBudgetPathFor={editBudgetPathFor}
          analyticsPath={analyticsPath}
          sortOrder={sortOrder}
          onSortChange={handleSortChange}
          canManageBudgets={canEdit}
        />
      </div>
    </Layout>
  )
}
