import {Spinner, TextInput} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {SearchIcon} from '@primer/octicons-react'
import {ItemPicker} from './ItemPicker'
import styles from './PickerDialog.module.css'

import type {Item} from '../../types/common'
import {useRef} from 'react'
import {useDebounce} from '@github-ui/use-debounce'

type Props<T> = {
  open: boolean
  resetDialog: () => void
  filter: (filter: string) => void
  selectAll: boolean
  selected: Array<Item<T>>
  onDialogSubmit: (newSelected: Array<Item<T>>, newSelectAll: boolean) => void
  items: Array<Item<T>>
  pickerType: string
  loading: boolean
  selectionVariant?: 'multiple' | 'single'
  entityType?: 'budget' | 'cost center' | 'report'
  totalItemsCount: number
  pageSize?: number
  pageCount?: number
  currentPage?: number
  onPageChange?: (event: React.MouseEvent, n: number) => void
  showPaginatedItems?: boolean
  /** Optional callback fired immediately when selection changes (for persisting across remounts) */
  onSelectionChange?: (newSelected: Array<Item<T>>) => void
}

// Define the default function outside the component
const defaultOnPageChange = () => {}

export function PickerDialog<T>({
  items,
  open,
  resetDialog,
  filter,
  selected,
  selectAll,
  onDialogSubmit,
  pickerType,
  loading,
  selectionVariant,
  entityType = 'budget',
  totalItemsCount,
  pageCount,
  currentPage,
  onPageChange = defaultOnPageChange,
  showPaginatedItems = false,
  onSelectionChange,
}: Props<T>) {
  const debouncedFilter = useDebounce((value: string) => {
    filter(value.toLowerCase())
  }, 750)

  const callFilterChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    debouncedFilter(event.target.value)
  }

  const returnFocusRef = useRef(null)

  if (!open) return null

  return (
    <Dialog
      role="dialog"
      onClose={() => resetDialog()}
      title={`Select ${pickerType}`}
      returnFocusRef={returnFocusRef}
      aria-labelledby="picker-header"
      className={styles.dialog}
    >
      <div>
        <div className={styles.content}>
          <p className={styles.description}>
            Select the {pickerType} to include in this {entityType}. You can only add/remove the {pickerType} that you
            have access to.
          </p>
          <TextInput
            block
            leadingVisual={SearchIcon}
            aria-label={pickerType}
            name={pickerType}
            placeholder={`Search ${pickerType}`}
            onChange={callFilterChange}
            disabled={selectAll}
            className={styles.searchInput}
          />
        </div>
      </div>
      {loading ? (
        <div className={styles.loadingContainer}>
          <Spinner />
        </div>
      ) : (
        <>
          <ItemPicker
            items={items}
            totalItemsCount={totalItemsCount}
            initialSelected={selected}
            initialSelectAll={selectAll}
            pickerType={pickerType}
            onDialogSubmit={onDialogSubmit}
            selectionVariant={selectionVariant}
            pageCount={pageCount ?? 0}
            currentPage={currentPage ?? 0}
            onPageChange={onPageChange}
            showPaginatedItems={showPaginatedItems}
            onSelectionChange={onSelectionChange}
          />
        </>
      )}
    </Dialog>
  )
}
