import {use} from 'react'
import {Link} from '@primer/react'
import {PageContext} from '../../App'

import {SummaryUsageCard} from '.'
import {getCurrentMonthDateRange} from '../../utils/date'
import useRoute from '../../hooks/use-route'
import {USAGE_ROUTE} from '../../routes'
import {GROUP_BY_COSTCENTER_TYPE} from '../../constants'
import {UsagePeriod} from '../../enums'

interface TotalUsageCardProps {
  totalUsage: number
  /** @deprecated This prop is no longer used and will be removed in a future version */
  usageMap?: Record<string, number>
  isLoadingTotalUsage: boolean
}

export default function TotalUsageCard({totalUsage, isLoadingTotalUsage, usageMap: _usageMap}: TotalUsageCardProps) {
  const {isEnterpriseRoute} = use(PageContext)
  const {path: usageUrl} = useRoute(
    USAGE_ROUTE,
    {},
    {group: GROUP_BY_COSTCENTER_TYPE.toString(), period: UsagePeriod.THIS_MONTH.toString()},
  )
  const headerAction = isEnterpriseRoute ? (
    <Link inline href={usageUrl}>
      More details
    </Link>
  ) : undefined

  return (
    <SummaryUsageCard
      headerAction={headerAction}
      heading="Current metered usage"
      description={`Gross metered usage for ${getCurrentMonthDateRange()}.`}
      monetaryValue={totalUsage}
      testId="total-usage"
      isLoading={isLoadingTotalUsage}
    />
  )
}
