import {ProgressBar} from '@primer/react'

type Props = {
  targetAmount: number
  currentAmount: number
}

export default function CreditProgressBar({currentAmount, targetAmount}: Props) {
  const isOverBudget = currentAmount > targetAmount

  // if targetAmount is 0, we want to show the progress bar as full (100%)
  const percentage = targetAmount === 0 ? 1 : currentAmount / targetAmount
  const progress = Math.min(percentage * 100, 100)

  let bg: string
  if (isOverBudget) {
    bg = 'danger.emphasis'
  } else if (targetAmount === 0 || percentage >= 0.9) {
    bg = 'attention.emphasis'
  } else {
    bg = 'accent.emphasis'
  }

  return (
    <ProgressBar
      progress={progress}
      bg={bg}
      barSize="small"
      aria-label="Credit utilization"
      data-testid="credit-progressbar"
    />
  )
}
