import type {PaginationProps} from '@primer/react'
import {Pagination} from '@primer/react'

import styles from './ResourcePaginator.module.css'

type onPageChangeType = PaginationProps['onPageChange']

interface Props {
  pageSize?: number
  pageCount: number
  currentPage: number
  onPageChange: onPageChangeType
  totalResources: number
}

export default function ResourcePaginator({
  pageSize = 10,
  pageCount,
  currentPage,
  totalResources,
  onPageChange,
}: Props) {
  return (
    <>
      {totalResources > pageSize && (
        <div className={styles.paginationWrapper} data-testid="pagination-wrapper">
          <p className={styles.pageText} data-testid="pagination-page-text">
            {currentPage === 1 ? 1 : (currentPage - 1) * pageSize + 1}-{currentPage * pageSize} of {totalResources}
          </p>
          <Pagination
            pageCount={pageCount}
            currentPage={currentPage}
            onPageChange={onPageChange}
            aria-label="Cost center resource pagination"
          />
        </div>
      )}
    </>
  )
}
