import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Heading} from '@primer/react'
import {InfoIcon} from '@primer/octicons-react'
import first from 'lodash-es/first'
import {useState, use} from 'react'
import {reverse} from '../utils/array'
import {PageContext} from '../App'
import {Layout, TrustTierBanner} from '../components'
import {BudgetBanner} from '../components/budget'
import {
  UsageFilters,
  ProductUsageContainer,
  OrgRepoUsageContainer,
  SubscriptionsContainer,
  TbbAnnouncementBanner,
} from '../components/usage'
import {VolumeLicensesCard} from '../components/licensing'
import {BILLING_MANAGER, ENTERPRISE_ORG_OWNER, OWNER} from '../constants'
import {UsagePeriod} from '../enums'
import SummaryCardContainer from '../components/usage/SummaryCardContainer'

import type {BudgetAlertDetails} from '../types/budgets'
import type {AdminRole, Customer} from '../types/common'
import type {EnabledProduct} from '../types/products'
import type {CustomerSelection, Filters, PeriodSelection} from '../types/usage'
import type {PaymentDueCardProps} from '../components/payment_due/PaymentDueCard'
import type {VolumeLicensesCardProps} from '../components/licensing/VolumeLicensesCard'
import type {LatestInvoiceCardProps} from '../components/invoices/LatestInvoiceCard'
import type {PrepaidCreditsCardProps} from '../components/prepaid_credits/PrepaidCreditsCard'
import type {NextPaymentCardProps} from '../components/payment_due/NextPaymentCard'
import PrepaidCreditsCard from '../components/prepaid_credits/PrepaidCreditsCard'
import type {CopilotForIndividualsData} from '../types/copilot-for-individuals'

import styles from './OverviewPage.module.css'

export interface OverviewPagePayload {
  admin_roles: AdminRole[]
  budget_alert_details: BudgetAlertDetails | null
  customer: Customer
  customer_selections: CustomerSelection[]
  enabled_products: EnabledProduct[]
  period_selections: PeriodSelection[]
  multi_tenant: boolean
  nextPaymentTileData: NextPaymentCardProps
  showPaymentDueTile: boolean
  paymentDueTileData: PaymentDueCardProps
  showLatestInvoiceTile: boolean
  latestInvoiceTileData: LatestInvoiceCardProps
  showVolumeLicenseSpendTile: boolean
  volumeLicenseSpendTileData: VolumeLicensesCardProps
  showPrepaidCredits: boolean
  prepaidCreditsTileData?: PrepaidCreditsCardProps
  taxDisclaimer: string
  isCopilotStandalone: boolean
  copilot_premium_usage_report_enabled: boolean
  copilotForIndividualsData?: CopilotForIndividualsData
  next_payment_card_enabled: boolean
  showTrustTierBanner?: boolean
  show_preview_bill?: boolean
  is_token_based_billing_enabled?: boolean
  billing_user_level_ai_units?: boolean
}

export function OverviewPage() {
  const isStafftoolsRoute = use(PageContext).isStafftoolsRoute
  const isEnterpriseRoute = use(PageContext).isEnterpriseRoute
  const isOrganizationRoute = use(PageContext).isOrganizationRoute
  const isUserRoute = use(PageContext).isUserRoute

  const payload = useRoutePayload<OverviewPagePayload>()
  const {
    admin_roles: adminRoles,
    budget_alert_details: budgetAlertDetails,
    customer,
    customer_selections,
    enabled_products: enabledProducts,
    period_selections: periodSelections,
    showPaymentDueTile,
    paymentDueTileData,
    nextPaymentTileData,
    showLatestInvoiceTile: showLatestInvoiceTile,
    latestInvoiceTileData,
    showVolumeLicenseSpendTile,
    volumeLicenseSpendTileData,
    showPrepaidCredits,
    prepaidCreditsTileData,
    taxDisclaimer,
    isCopilotStandalone,
    copilot_premium_usage_report_enabled,
    copilotForIndividualsData,
    next_payment_card_enabled: nextPaymentCardEnabled,
    showTrustTierBanner,
    show_preview_bill: showPreviewBill,
    is_token_based_billing_enabled: isTokenBasedBillingEnabled,
    billing_user_level_ai_units: isUserLevelAiUnitsEnabled,
  } = payload
  // The default selected customer is the last customer in the customerSelections array.
  // The reverse method is used to reverse the order of the array so that the default selected customer
  // is shown as the first item in the customer selection dropdown.
  const customerSelections = reverse(customer_selections)
  const [filters, setFilters] = useState<Filters>(() => ({
    customer: first(customerSelections) as CustomerSelection,
    group: undefined,
    period: periodSelections.find((obj: PeriodSelection) => obj.type === UsagePeriod.DEFAULT),
    product: undefined,
    sku: undefined,
    searchQuery: '',
  }))

  // TODO: Filter based on the product
  const isAdmin = adminRoles.includes(OWNER) || adminRoles.includes(BILLING_MANAGER)
  const isOnlyOrgAdmin = !isAdmin && adminRoles.includes(ENTERPRISE_ORG_OWNER)
  const canViewDiscountUsage =
    adminRoles.includes(OWNER) ||
    adminRoles.includes(BILLING_MANAGER) ||
    isOrganizationRoute ||
    isOnlyOrgAdmin ||
    (isStafftoolsRoute && isEnterpriseRoute)

  const showTbbAnnouncementBanner =
    showPreviewBill && (isStafftoolsRoute || isUserRoute || (isAdmin && (isEnterpriseRoute || isOrganizationRoute)))

  return (
    <Layout data-hpc>
      {showTrustTierBanner && <TrustTierBanner isAdmin={isAdmin} />}
      {budgetAlertDetails && <BudgetBanner budgetAlertDetail={budgetAlertDetails} />}
      {showTbbAnnouncementBanner && <TbbAnnouncementBanner />}
      <header>
        <Heading as="h1" className={styles.mainHeading}>
          Overview
        </Heading>
      </header>
      <SummaryCardContainer
        canViewDiscountUsage={canViewDiscountUsage}
        customerSelections={customerSelections}
        enabledProducts={enabledProducts}
        isCopilotPremiumUsageReportEnabled={copilot_premium_usage_report_enabled}
        isOnlyOrgAdmin={isOnlyOrgAdmin}
        latestInvoiceTileData={latestInvoiceTileData}
        nextPaymentCardEnabled={nextPaymentCardEnabled}
        nextPaymentTileData={nextPaymentTileData}
        paymentDueTileData={paymentDueTileData}
        showPaymentDueTile={showPaymentDueTile}
        showLatestInvoiceTile={showLatestInvoiceTile}
        isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
      />
      {!isEnterpriseRoute && copilotForIndividualsData && (
        <div className={styles.container}>
          <SubscriptionsContainer customer={customer} copilotForIndividualsData={copilotForIndividualsData} />
        </div>
      )}
      {taxDisclaimer && (
        <div className={styles.disclaimerContainer}>
          <div data-testid="sales-tax-disclaimer-fineprint" className={styles.Box_2}>
            <InfoIcon size={16} className={styles.infoIcon} />
            <p className={styles.disclaimerText}>{taxDisclaimer}</p>
          </div>
        </div>
      )}
      {showVolumeLicenseSpendTile && (
        <div className={styles.container}>
          <VolumeLicensesCard {...volumeLicenseSpendTileData} />
        </div>
      )}
      {showPrepaidCredits && <PrepaidCreditsCard {...prepaidCreditsTileData} />}
      <div className={styles.headingContainer}>
        <Heading as="h2" className={styles.heading}>
          Metered usage
        </Heading>

        <UsageFilters
          customer={customer}
          filters={filters}
          setFilters={setFilters}
          periodSelections={periodSelections}
          showSearch={false}
        />
      </div>
      <div className={styles.container}>
        <ProductUsageContainer
          customer={customer}
          enabledProducts={enabledProducts}
          filters={filters}
          isCopilotStandalone={isCopilotStandalone}
          isOnlyOrgAdmin={isOnlyOrgAdmin}
          isTokenBasedBillingEnabled={isTokenBasedBillingEnabled}
          isUserLevelAiUnitsEnabled={isUserLevelAiUnitsEnabled}
        />

        <OrgRepoUsageContainer filters={filters} />
      </div>
    </Layout>
  )
}
