import type {KeyboardEventHandler} from 'react'
import {useState, useCallback, useRef, use} from 'react'
import {useRelayEnvironment} from 'react-relay'
import {QueryBuilder} from '@github-ui/query-builder/QueryBuilder'
import {useDebounce} from '@github-ui/use-debounce'
import type {QueryBuilderElement} from '@github-ui/query-builder-element'
import {BillingEnterpriseUserFilterProvider} from '@github-ui/query-builder/providers/billing/billing-enterprise-user-filter-provider'
import {BillingOrganizationUserFilterProvider} from '@github-ui/query-builder/providers/billing/billing-organization-user-filter-provider'
import {BillingBudgetThresholdFilterProvider} from '@github-ui/query-builder/providers/billing/billing-budget-threshold-filter-provider'

import {PageContext} from '../../App'

interface MultiUserBudgetSearchBarProps {
  customerDisplayId: string
  searchQuery: string
  setSearchQuery: (query: string) => void
  isEnterpriseOrgAdmin?: boolean
}

export default function MultiUserBudgetSearchBar({
  customerDisplayId,
  searchQuery,
  setSearchQuery,
  isEnterpriseOrgAdmin = false,
}: MultiUserBudgetSearchBarProps) {
  const [inputQuery, setInputQuery] = useState<string>(searchQuery)
  const relayEnvironment = useRelayEnvironment()
  const ref = useRef(null)
  const {isEnterpriseRoute, isOrganizationRoute, isStafftoolsRoute} = use(PageContext)

  const debouncedSetSearchQuery = useDebounce(setSearchQuery, 400)

  const onRequestProvider = useCallback(
    (event: Event) => {
      event.stopPropagation()
      const queryBuilder = event.target as QueryBuilderElement

      // User filter — respects org admin visibility constraints
      // Org admins can only see users in their own org, so we use the org-scoped provider;
      // enterprise owners/billing managers get the enterprise-wide user list.
      const shouldShowUserFilter =
        isOrganizationRoute || (isEnterpriseRoute && (!isEnterpriseOrgAdmin || isStafftoolsRoute))

      if (shouldShowUserFilter) {
        const UserFilterProvider = isEnterpriseRoute
          ? BillingEnterpriseUserFilterProvider
          : BillingOrganizationUserFilterProvider

        new UserFilterProvider(queryBuilder, {
          name: 'User',
          value: 'user',
          priority: 1,
          slug: customerDisplayId,
          relayEnvironment,
        })
      }

      // Budget threshold filter — static list of threshold ranges
      new BillingBudgetThresholdFilterProvider(queryBuilder, {
        name: 'Budget threshold',
        value: 'threshold',
        priority: 2,
      })
    },
    [
      customerDisplayId,
      relayEnvironment,
      isEnterpriseRoute,
      isOrganizationRoute,
      isStafftoolsRoute,
      isEnterpriseOrgAdmin,
    ],
  )

  const onChangeHandler: React.ChangeEventHandler<HTMLInputElement> = useCallback(
    event => {
      const newInputQuery = event.currentTarget.value

      if (newInputQuery !== inputQuery) {
        // Input was cleared — reset query
        if (newInputQuery === '') {
          debouncedSetSearchQuery.cancel()
          setSearchQuery('')
          setInputQuery('')
          return
        }

        setInputQuery(newInputQuery)

        // Submit once the user has finished typing/selecting a filter with a value
        const searchCount = newInputQuery.split(':').length - 1
        if (newInputQuery.includes(':') && !newInputQuery.trim().endsWith(':') && searchCount === 1) {
          debouncedSetSearchQuery(newInputQuery.trim())
        }
      }
    },
    [inputQuery, setSearchQuery, debouncedSetSearchQuery],
  )

  const handleEnterKeyPress: KeyboardEventHandler = useCallback(
    event => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic -- manual shortcut logic is idiomatic in React
      if (event.key !== 'Enter') return
      event.preventDefault()
      const searchCount = inputQuery.split(':').length - 1
      if (searchCount === 1) {
        setSearchQuery(inputQuery.trim())
      }
    },
    [inputQuery, setSearchQuery],
  )

  return (
    <QueryBuilder
      id="multi-user-budget-query-builder"
      label="Search or filter by user or budget threshold"
      onChange={onChangeHandler}
      onKeyPress={handleEnterKeyPress}
      inputValue={inputQuery}
      placeholder="Filter by user or budget threshold"
      onRequestProvider={onRequestProvider}
      data-testid="search-multi-user-budgets"
      inputRef={ref}
    />
  )
}
