const THRESHOLD_BOUNDS: Record<string, {lowerBound: number | undefined; upperBound: number | undefined}> = {
  all: {lowerBound: undefined, upperBound: undefined},
  '1-75': {lowerBound: 1, upperBound: 75},
  '76-89': {lowerBound: 76, upperBound: 89},
  '90-99': {lowerBound: 90, upperBound: 99},
  '100': {lowerBound: 100, upperBound: undefined},
}

export interface MultiUserBudgetFilters {
  username: string
  thresholdLowerBound: number | undefined
  thresholdUpperBound: number | undefined
}

/**
 * Parses a QueryBuilder search query (e.g. "user:octocat" or "threshold:76-89")
 * into structured filter parameters for the multi-user budget states hook.
 */
export function parseMultiUserBudgetQuery(query: string): MultiUserBudgetFilters {
  const result: MultiUserBudgetFilters = {
    username: '',
    thresholdLowerBound: undefined,
    thresholdUpperBound: undefined,
  }

  if (!query) return result

  const trimmed = query.trim()

  if (trimmed.startsWith('user:')) {
    result.username = trimmed.replace('user:', '').trim()
  } else if (trimmed.startsWith('threshold:')) {
    const thresholdValue = trimmed.replace('threshold:', '').trim()
    const bounds = THRESHOLD_BOUNDS[thresholdValue]
    if (bounds) {
      result.thresholdLowerBound = bounds.lowerBound
      result.thresholdUpperBound = bounds.upperBound
    }
  }

  return result
}
