import {getCurrentMonthDateRange} from '../../utils'

import SummaryUsageCard from './SummaryUsageCard'

interface Props {
  estimatedNextPaymentValue: number
  isLoadingValue: boolean
}

export default function EstimatedNextPaymentCard({estimatedNextPaymentValue, isLoadingValue}: Props) {
  return (
    <SummaryUsageCard
      heading="Estimated next payment"
      description={`Estimated next payment due for the ${getCurrentMonthDateRange()} billing cycle.`}
      monetaryValue={estimatedNextPaymentValue}
      testId="estimated-next-payment"
      isLoading={isLoadingValue}
    />
  )
}
