import {GitHubAvatar} from '@github-ui/github-avatar'
import {ItemPicker} from '@github-ui/item-picker-base/ItemPicker'
import {debounce} from '@github/mini-throttle'
// eslint-disable-next-line no-restricted-imports
import {useToastContext} from '@github-ui/toast/ToastContext'
import {LockIcon, TriangleDownIcon} from '@primer/octicons-react'
import {Button} from '@primer/react'
import {useCallback, useMemo, useState, useEffect} from 'react'

import type {PreloadedQuery} from 'react-relay'

import {fetchQuery, graphql, readInlineData, usePreloadedQuery, useRelayEnvironment} from 'react-relay'
import pluralize from 'pluralize'

import {SelectedRows} from './SelectedRows'
import styles from './UserPicker.module.css'

import type {
  UserPickerUserFragment$key,
  UserPickerUserFragment$data,
} from './__generated__/UserPickerUserFragment.graphql'
// After renaming the query, this import will need to be updated to the newly generated type
import type {
  UserPickerEnterpriseOwnersQuery as UserPickerEnterpriseOwnersQueryType,
  UserPickerEnterpriseOwnersQuery$data,
} from './__generated__/UserPickerEnterpriseOwnersQuery.graphql'
import type {
  UserPickerSearchQuery as UserPickerSearchQueryType,
  UserPickerSearchQuery$data,
} from './__generated__/UserPickerSearchQuery.graphql'

interface Props {
  viewOnly?: boolean
  slug: string
  onSelectionChange: (selected: User[]) => void
  initialUsers: User[]
  preloadedData:
    | {type: 'roleBasedMembers'; data: PreloadedQuery<UserPickerSearchQueryType>}
    | {type: 'enterpriseOwners'; data: PreloadedQuery<UserPickerEnterpriseOwnersQueryType>}
  itemType?: 'users' | 'recipients'
  selectionVariant?: 'single' | 'multiple'
}

const getAriaMessages = (itemType: 'users' | 'recipients' = 'users') => ({
  SEARCHING: 'Searching...',
  SEARCH_CLEARED: 'Search cleared',
  ERROR_SEARCHING: 'Search error',
  NO_USERS_FOUND: (query: string) => `No ${itemType} found for "${query}"`,
  USERS_FOUND: (count: number, query: string) =>
    `${count} ${pluralize(itemType.slice(0, -1), count)} found for "${query}"`,
  USERS_SELECTED: (count: number) => `${count} selected`,
})

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
export const UserPickerSearchQuery = graphql`
  query UserPickerSearchQuery($slug: String!, $query: String) {
    enterprise(slug: $slug) {
      organizationsMembers(phrase: $query, first: 10) {
        nodes {
          ... on User {
            ...UserPickerUserFragment
          }
        }
      }
    }
  }
`

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
export const UserPickerUserFragment = graphql`
  fragment UserPickerUserFragment on User @inline {
    id
    # eslint-disable-next-line relay/unused-fields -- consumed by BudgetScopeSelector via readInlineData
    databaseId
    login
    name
    avatarUrl(size: 64)
  }
`

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
export const UserPickerEnterpriseOwnersQuery = graphql`
  query UserPickerEnterpriseOwnersQuery($slug: String!) {
    enterprise(slug: $slug) {
      ownerInfo {
        admins(first: 10) {
          nodes {
            ...UserPickerUserFragment
          }
        }
      }
    }
  }
`

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
export const UserPickerInitialUsersQuery = graphql`
  query UserPickerInitialUsersQuery($ids: [ID!]!) {
    nodes(ids: $ids) {
      ... on User {
        ...UserPickerUserFragment
      }
    }
  }
`

// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-queries
export const UserPickerInitialUsersByRoleQuery = graphql`
  query UserPickerInitialUsersByRoleQuery($slug: String!, $ids: [ID!]!, $limit: Int!) {
    enterprise(slug: $slug) {
      organizationsMembers(ids: $ids, first: $limit) {
        nodes {
          ... on User {
            ...UserPickerUserFragment
          }
        }
      }
    }
  }
`

export type User = UserPickerUserFragment$data & {
  viewOnly?: boolean
}

const sortUsers = (recipients: User[], usersToSort: User[]) => {
  return usersToSort.slice().sort((a, b) => {
    const aIsRecipient = recipients.some(r => r.login === a.login)
    const bIsRecipient = recipients.some(r => r.login === b.login)
    if (aIsRecipient && !bIsRecipient) return -1
    if (bIsRecipient && !aIsRecipient) return 1
    return a.login?.localeCompare(b.login)
  })
}

// Helper components to handle each query type separately
const EnterpriseOwnersUserPicker = ({
  slug,
  onSelectionChange,
  preloadedData,
  initialUsers,
  itemType = 'users',
  selectionVariant = 'multiple',
}: {
  slug: string
  onSelectionChange: (selected: User[]) => void
  preloadedData: PreloadedQuery<UserPickerEnterpriseOwnersQueryType>
  initialUsers: User[]
  itemType?: 'users' | 'recipients'
  selectionVariant?: 'single' | 'multiple'
}) => {
  const data = usePreloadedQuery<UserPickerEnterpriseOwnersQueryType>(UserPickerEnterpriseOwnersQuery, preloadedData)

  return (
    <UserPickerImpl
      slug={slug}
      onSelectionChange={onSelectionChange}
      initialUsers={initialUsers}
      userType="enterpriseOwners"
      enterpriseOwnersData={data}
      allEnterpriseMembersData={null}
      itemType={itemType}
      selectionVariant={selectionVariant}
    />
  )
}

const AllEnterpriseMembersUserPicker = ({
  slug,
  onSelectionChange,
  preloadedData,
  initialUsers,
  itemType = 'users',
  selectionVariant = 'multiple',
}: {
  slug: string
  onSelectionChange: (selected: User[]) => void
  preloadedData: PreloadedQuery<UserPickerSearchQueryType>
  initialUsers: User[]
  itemType?: 'users' | 'recipients'
  selectionVariant?: 'single' | 'multiple'
}) => {
  const data = usePreloadedQuery<UserPickerSearchQueryType>(UserPickerSearchQuery, preloadedData)

  return (
    <UserPickerImpl
      slug={slug}
      onSelectionChange={onSelectionChange}
      initialUsers={initialUsers}
      userType="roleBasedMembers"
      enterpriseOwnersData={null}
      allEnterpriseMembersData={data}
      itemType={itemType}
      selectionVariant={selectionVariant}
    />
  )
}

export const UserPicker = ({
  viewOnly,
  slug,
  onSelectionChange,
  preloadedData,
  initialUsers,
  itemType = 'users',
  selectionVariant = 'multiple',
}: Props) => {
  if (viewOnly) {
    return (
      <div data-testid="user-picker-viewonly">
        <SelectedRows
          removeOption={() => {}}
          selected={initialUsers.map(user => ({
            id: user.id,
            text: user.viewOnly ? 'Insufficient permission to view' : user.login,
            description: user.name ?? '',
            source: user,
            leadingVisual: () => (user.viewOnly ? <LockIcon /> : <GitHubAvatar src={user.avatarUrl} alt="" />),
            rowLeadingVisual: () => (user.viewOnly ? <LockIcon /> : <GitHubAvatar src={user.avatarUrl} alt="" />),
            viewOnly: true,
          }))}
        />
      </div>
    )
  }
  if (preloadedData.type === 'enterpriseOwners') {
    return (
      <EnterpriseOwnersUserPicker
        slug={slug}
        onSelectionChange={onSelectionChange}
        preloadedData={preloadedData.data}
        initialUsers={initialUsers}
        itemType={itemType}
        selectionVariant={selectionVariant}
      />
    )
  } else {
    return (
      <AllEnterpriseMembersUserPicker
        slug={slug}
        onSelectionChange={onSelectionChange}
        preloadedData={preloadedData.data}
        initialUsers={initialUsers}
        itemType={itemType}
        selectionVariant={selectionVariant}
      />
    )
  }
}

const Footer = ({
  selectedCount,
  reAssignedCount,
  onSelect,
  itemType = 'users',
}: {
  selectedCount: number
  reAssignedCount: number
  onSelect: () => void
  itemType?: 'users' | 'recipients'
}) => {
  const itemLabel = itemType === 'recipients' ? 'recipient' : 'user'
  return (
    <div className={styles.selectionFooter}>
      <span>
        {
          reAssignedCount > 0
            ? `${reAssignedCount} ${pluralize(itemLabel, reAssignedCount)} will be reassigned.`
            : '\u00A0' // Non-breaking space to maintain layout
        }
      </span>
      <Button
        variant="primary"
        className={styles.selectButton}
        onClick={() => {
          onSelect()
        }}
      >
        Select{selectedCount > 0 && <span> {selectedCount}</span>}
      </Button>
    </div>
  )
}

const UserPickerImpl = ({
  slug,
  onSelectionChange,
  initialUsers,
  userType,
  enterpriseOwnersData,
  allEnterpriseMembersData,
  itemType = 'users',
  selectionVariant = 'multiple',
}: {
  slug: string
  onSelectionChange: (selected: User[]) => void
  initialUsers: User[]
  userType: 'enterpriseOwners' | 'roleBasedMembers'
  enterpriseOwnersData: UserPickerEnterpriseOwnersQuery$data | null
  allEnterpriseMembersData: UserPickerSearchQuery$data | null
  itemType?: 'users' | 'recipients'
  selectionVariant?: 'single' | 'multiple'
}) => {
  const ARIA_MESSAGES = getAriaMessages(itemType)
  const [loading, setLoading] = useState<boolean>(false)
  const [searchResults, setSearchResults] = useState<User[] | undefined>()
  const [recipients, setRecipients] = useState<User[]>([])
  const [selectedUsers, setSelectedUsers] = useState<User[]>([])
  const [reAssignedCount] = useState(0)
  const [filter, setFilter] = useState<string>('')
  const [ariaMessage, setAriaMessage] = useState<string>('')
  const [shouldAnnounceResults, setShouldAnnounceResults] = useState<boolean>(false)
  const [pickerOpen, setPickerOpen] = useState(false)
  const environment = useRelayEnvironment()
  const {addToast} = useToastContext()

  const dropDownText = useMemo(() => {
    if (userType === 'enterpriseOwners') return 'Select recipients'
    if (selectionVariant === 'single') {
      const selected = recipients.find(r => !r.viewOnly)
      return selected ? selected.login : 'Select user'
    }
    return 'Select users'
  }, [userType, selectionVariant, recipients])

  function getUsersFromData(): User[] {
    switch (userType) {
      case 'enterpriseOwners': {
        if (!enterpriseOwnersData) return []
        return (enterpriseOwnersData.enterprise?.ownerInfo?.admins.nodes || []).flatMap(node =>
          // eslint-disable-next-line no-restricted-syntax
          node ? [readInlineData<UserPickerUserFragment$key>(UserPickerUserFragment, node)] : [],
        )
      }
      case 'roleBasedMembers': {
        if (!allEnterpriseMembersData) return []
        return (allEnterpriseMembersData.enterprise?.organizationsMembers?.nodes || []).flatMap(node =>
          // eslint-disable-next-line no-restricted-syntax
          node ? [readInlineData<UserPickerUserFragment$key>(UserPickerUserFragment, node)] : [],
        )
      }
      default:
        return []
    }
  }

  const enterpriseOwners = getUsersFromData()
  const getItemKey = useCallback((user: User) => user.login, [])

  const items = useMemo(() => {
    if (searchResults) {
      const merged = [...recipients, ...searchResults.filter(u => !recipients.find(r => r.id === u.id))]
      return sortUsers(recipients, merged)
    }
    if (enterpriseOwners.length > 0) {
      return sortUsers(
        recipients,
        recipients.concat(enterpriseOwners.filter(u => !recipients.find(r => r.login === u.login))),
      )
    }
    return recipients
  }, [searchResults, recipients, enterpriseOwners])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setRecipients(initialUsers)
    setSelectedUsers(initialUsers)
  }, [initialUsers])

  const convertToItemProps = useCallback((user: User) => {
    return {
      id: user.id,
      text: user.viewOnly ? 'Insufficient permission to view' : user.login,
      description: user.name ?? '',
      source: user,
      leadingVisual: () => (user.viewOnly ? <LockIcon /> : <GitHubAvatar src={user.avatarUrl} alt="" />),
      rowLeadingVisual: () => (user.viewOnly ? <LockIcon /> : <GitHubAvatar src={user.avatarUrl} alt="" />),
      viewOnly: !!user.viewOnly,
    }
  }, [])

  // Create a version on for ItemPicker to prevent DOM attribute warnings
  const convertToItemPropsForPicker = useCallback(
    (user: User) => {
      const {viewOnly, ...itemProps} = convertToItemProps(user)
      return itemProps
    },
    [convertToItemProps],
  )

  const onClose = useCallback(() => {
    setSearchResults(undefined)
  }, [])

  const removeOption = (id: string) => {
    const newRecipients = recipients.filter(r => r.id !== id)
    setRecipients(newRecipients)
    setSelectedUsers(newRecipients)
    onSelectionChange(newRecipients)
  }

  const fetchSearchData = useCallback(
    (query: string) => {
      if (query === '') {
        setSearchResults(undefined)
        setShouldAnnounceResults(true)
        setAriaMessage(ARIA_MESSAGES.SEARCH_CLEARED)
        return
      }
      setLoading(true)

      fetchQuery<UserPickerSearchQueryType>(environment, UserPickerSearchQuery, {slug, query}).subscribe({
        next: data => {
          const nodes = (data.enterprise?.organizationsMembers?.nodes || []).flatMap(node =>
            // eslint-disable-next-line no-restricted-syntax
            node ? [readInlineData<UserPickerUserFragment$key>(UserPickerUserFragment, node)] : [],
          )
          setSearchResults(nodes)
          setLoading(false)
          setShouldAnnounceResults(true)

          if (nodes.length === 0) {
            setAriaMessage(ARIA_MESSAGES.NO_USERS_FOUND(query))
          } else {
            // Only announce detailed results for small result sets to reduce noise
            if (nodes.length <= 3) {
              setAriaMessage(ARIA_MESSAGES.USERS_FOUND(nodes.length, query))
            } else {
              setAriaMessage(`${nodes.length} users found`)
            }
          }
        },
        error: () => {
          setLoading(false)
          setShouldAnnounceResults(true)
          // eslint-disable-next-line @github-ui/dotcom-primer/toast-migration
          addToast({
            type: 'error',
            message: 'Unable to query users',
            role: 'alert',
          })
          setAriaMessage(ARIA_MESSAGES.ERROR_SEARCHING)
        },
      })
    },
    [slug, environment, addToast, ARIA_MESSAGES],
  )

  const debounceFetchSearchData = useMemo(
    () => debounce((nextValue: string) => fetchSearchData(nextValue), 200),
    [fetchSearchData],
  )

  const filterItems = useCallback(
    (value: string) => {
      const trimmedFilter = value.trim()
      if (filter !== trimmedFilter) {
        setAriaMessage(ARIA_MESSAGES.SEARCHING)
        setShouldAnnounceResults(false)
        debounceFetchSearchData(trimmedFilter)
      }
      setFilter(value)
    },
    [debounceFetchSearchData, filter, ARIA_MESSAGES],
  )

  const mergeSelections = (existingSelections: User[], visibleSelections: User[]) => {
    const viewOnlySelections = existingSelections.filter(user => user.viewOnly)
    const idsOfItemsCurrentlyVisible = new Set(items.map(item => item.id))
    const idsOfItemsJustSelected = new Set(visibleSelections.map(user => user.id))

    const hiddenButStillSelected = existingSelections.filter(
      user => !idsOfItemsCurrentlyVisible.has(user.id) && !idsOfItemsJustSelected.has(user.id),
    )

    // Combine view only selections with what user just selected and with what was previously selected but hidden
    return [...visibleSelections, ...hiddenButStillSelected, ...viewOnlySelections]
  }

  const onSelectedChanged = (selected: User[]) => {
    const merged = mergeSelections(selectedUsers, selected)
    setSelectedUsers(merged)

    // For single selection, the picker auto-closes on item click, so the
    // footer "Select" button is never reached.  Propagate immediately.
    if (selectionVariant === 'single') {
      setRecipients(merged)
      onSelectionChange(merged)
      setPickerOpen(false)
    }

    setShouldAnnounceResults(true)
    setAriaMessage(ARIA_MESSAGES.USERS_SELECTED(merged.length))
  }

  const onLiveSelectionChange = (selected: User[]) => {
    const merged = mergeSelections(selectedUsers, selected)
    setSelectedUsers(merged)
  }

  const confirmSelection = useCallback(() => {
    setRecipients(selectedUsers)
    onSelectionChange(selectedUsers)
    setPickerOpen(false)
  }, [selectedUsers, onSelectionChange])

  return (
    <div data-testid="user-picker">
      <div className={styles.pickerWrapper}>
        <ItemPicker
          items={items.filter(item => !item.viewOnly)}
          initialSelectedItems={selectedUsers.filter(item => !item.viewOnly)}
          filterItems={filterItems}
          getItemKey={getItemKey}
          convertToItemProps={convertToItemPropsForPicker}
          placeholderText={`Search for ${itemType}`}
          selectionVariant={selectionVariant}
          loading={loading}
          onSelectionChange={onSelectedChanged}
          onLiveSelectionChange={onLiveSelectionChange}
          onClose={onClose}
          title={`Select ${itemType}`}
          footer={
            <Footer
              selectedCount={selectedUsers.filter(item => !item.viewOnly).length}
              reAssignedCount={reAssignedCount}
              onSelect={confirmSelection}
            />
          }
          renderAnchor={anchorProps => (
            <Button
              trailingAction={TriangleDownIcon}
              {...anchorProps}
              onClick={e => {
                if (anchorProps.onClick) anchorProps.onClick(e)
                setPickerOpen(true)
                setSelectedUsers(recipients)
              }}
            >
              {dropDownText}
            </Button>
          )}
          aria-label="User picker"
          width="large"
          improvedNoMatchAccessibility
          triggerOpen={pickerOpen}
        />
      </div>
      <div className="sr-only" role="status" aria-live="polite" aria-atomic="true">
        {shouldAnnounceResults ? ariaMessage : ''}
      </div>
      {selectionVariant !== 'single' && (
        <SelectedRows
          removeOption={removeOption}
          selected={recipients.map(recipient => ({
            ...convertToItemProps(recipient),
          }))}
        />
      )}
    </div>
  )
}
